/**
 * R261/R262 sticky-overlay guard — defense against the mid-trade flicker the
 * operator reported in img20/img21, refined in R262 so the trade timer
 * keeps ticking during the replay window (was frozen on the initial R261
 * implementation).
 *
 * Why this module exists:
 *   The timer-driven base flow walks `analyzing → signal → executing`.
 *   Real trade state
 *   is layered on top via `resolveTradeOverlay` in `robot-trade-flow.ts`.
 *   When that overlay momentarily returns `null` between polls (e.g. SSE
 *   invalidation race, cache miss during cycle wrap), the base flow paints
 *   "PROCESSAMENTO NEURAL" for a frame — even though a trade is still in
 *   flight. The user sees the analyzing banner flash before active_trade
 *   reappears, then a frozen timer when R261 replays a static snapshot.
 *
 * What this module does:
 *   - `reconcileStickyOverlay` records every active_trade/result overlay it
 *     sees ALONG WITH the underlying `TradeView` so it can hand the trade
 *     back to the caller's rebuilder during a replay. The rebuilder
 *     recomputes `expiresInSeconds`/`progressPercent` from `nowMs`, so the
 *     replayed overlay tracks wall-clock time instead of freezing on the
 *     instant of observation.
 *   - `assertNoStageBackslide` is the runtime contract: stage MUST NOT
 *     regress from active_trade/result back to analyzing
 *     while a pending trade is known. Used by tests as the canonical
 *     specification.
 */
import type { MutableRefObject } from "react";
import type { TradeView } from "@/features/trade/types";
import type { RobotTradeOverlay } from "./robot-trade-flow";
import type { RobotVisualFlow } from "./robot-visual-flow";

/** Window in which a recently-observed `active_trade`/`result` overlay
 * keeps painting after the upstream `resolveTradeOverlay` momentarily
 * returns null. 10 s covers one `/trade/active` poll cycle (5 s) + worst-
 * case 5 s SSE/invalidation race; longer would mask real settle events,
 * shorter would let the bug reappear. */
export const STICKY_OVERLAY_TTL_MS = 10_000;
export const ACTIVE_TRADE_STICKY_SETTLING_GRACE_MS = 12_000;

export type StickyOverlayState = {
  readonly tradeView: TradeView;
  readonly sessionProfitCents: number;
  readonly observedAtMs: number;
  readonly capturedStage: Extract<
    RobotTradeOverlay["stage"],
    "active_trade" | "result"
  >;
};

/** Caller-provided closure used to recompute an overlay from a stored
 *  `TradeView` when the upstream `resolveTradeOverlay` returns null. The
 *  rebuilder runs the same code path as a normal render — pending trades
 *  get fresh `expiresInSeconds`, settled trades get the cooldown-aware
 *  result overlay (or null if cooldown elapsed).
 */
export type StickyOverlayRebuilder = (params: {
  readonly tradeView: TradeView;
  readonly sessionProfitCents: number;
  readonly nowMs: number;
}) => RobotTradeOverlay | null;

const TRADE_LOCKED_STAGES = new Set<RobotTradeOverlay["stage"]>([
  "active_trade",
  "result",
]);

function isLockedStage(
  stage: RobotTradeOverlay["stage"],
): stage is "active_trade" | "result" {
  return TRADE_LOCKED_STAGES.has(stage);
}

/** Replay the last `active_trade`/`result` overlay through a transient null
 * window while a trade is still believed to be in flight (pending in cache
 * or a placeTrade mutation in flight). Pure helper so the invariant test
 * can exercise it without React.
 *
 * Example: `reconcileStickyOverlay({ overlay: null, upstreamTradeView:
 *  null, hasPendingTradeInCache: true, nowMs, sessionProfitCents,
 *  stickyRef, rebuilder })` returns a freshly-rebuilt overlay from the
 *  stored TradeView if within `STICKY_OVERLAY_TTL_MS`, else null.
 */
// eslint-disable-next-line complexity
export function reconcileStickyOverlay(params: {
  readonly overlay: RobotTradeOverlay | null;
  readonly upstreamTradeView: TradeView | null | undefined;
  readonly hasPendingTradeInCache: boolean;
  readonly nowMs: number;
  readonly sessionProfitCents: number;
  readonly stickyRef: MutableRefObject<StickyOverlayState | null>;
  readonly rebuilder: StickyOverlayRebuilder;
}): RobotTradeOverlay | null {
  const {
    overlay,
    upstreamTradeView,
    hasPendingTradeInCache,
    nowMs,
    sessionProfitCents,
    stickyRef,
    rebuilder,
  } = params;
  // R262 v4: phase 1 — track the LATEST known state of the trade. When
  // upstream returns a tradeView, sync the sticky to reflect status
  // transitions (pending → win/loss) so we never serve a stale "active
  // trade" replay after the trade actually settled. TTL only refreshes
  // when upstream positively confirms pending — null upstream is treated
  // as "no fresh evidence" and the sticky ages out naturally.
  if (upstreamTradeView) {
    const current = stickyRef.current;
    const nextCapturedStage: "active_trade" | "result" =
      upstreamTradeView.status === "pending" ? "active_trade" : "result";
    const sameTrade = current?.tradeView.id === upstreamTradeView.id;
    const statusChanged =
      sameTrade && current?.tradeView.status !== upstreamTradeView.status;
    if (!current || !sameTrade || statusChanged) {
      stickyRef.current = {
        tradeView: upstreamTradeView,
        sessionProfitCents,
        observedAtMs: nowMs,
        capturedStage: nextCapturedStage,
      };
    } else if (upstreamTradeView.status === "pending") {
      // Same pending trade re-observed — refresh TTL anchor.
      stickyRef.current = { ...current, observedAtMs: nowMs };
    }
  }
  // Phase 2 — overlay non-null path. Capture-on-overlay still wins (kept
  // for tests that drive the guard without `upstreamTradeView`), but the
  // phase-1 refresh above already covers the live SPA path.
  if (overlay && isLockedStage(overlay.stage) && upstreamTradeView) {
    stickyRef.current = {
      tradeView: upstreamTradeView,
      sessionProfitCents,
      observedAtMs: nowMs,
      capturedStage: overlay.stage,
    };
    return overlay;
  }
  if (overlay) return overlay;
  const sticky = stickyRef.current;
  if (!sticky) return null;
  if (shouldReleaseStickyOverlay(sticky, nowMs)) {
    stickyRef.current = null;
    return null;
  }
  // Phase 3 — replay sticky to cover transient null window between polls.
  // For `active_trade` stickys (trade believed pending), the rebuilder
  // rebuilds the overlay with current `nowMs` so the timer keeps ticking.
  // For `result` stickys, only replay during the cooldown window
  // (hasPendingTradeInCache gates against a stale result through idle).
  if (sticky.capturedStage === "active_trade") {
    return rebuilder({
      tradeView: sticky.tradeView,
      sessionProfitCents: sticky.sessionProfitCents,
      nowMs,
    });
  }
  if (!hasPendingTradeInCache) return null;
  return rebuilder({
    tradeView: sticky.tradeView,
    sessionProfitCents: sticky.sessionProfitCents,
    nowMs,
  });
}

function shouldReleaseStickyOverlay(
  sticky: StickyOverlayState,
  nowMs: number,
): boolean {
  if (sticky.capturedStage !== "active_trade") {
    return nowMs - sticky.observedAtMs >= STICKY_OVERLAY_TTL_MS;
  }
  const releaseAtMs = activeTradeReleaseAtMs(sticky.tradeView);
  if (releaseAtMs === null)
    return nowMs - sticky.observedAtMs >= STICKY_OVERLAY_TTL_MS;
  return nowMs >= releaseAtMs;
}

function activeTradeReleaseAtMs(tradeView: TradeView): number | null {
  const expiresAtMs = readTradeExpiryMs(tradeView);
  if (expiresAtMs === null) return null;
  return expiresAtMs + ACTIVE_TRADE_STICKY_SETTLING_GRACE_MS;
}

function readTradeExpiryMs(tradeView: TradeView): number | null {
  if (typeof tradeView.expirationTimestamp === "number") {
    return tradeView.expirationTimestamp;
  }
  if (tradeView.serverExpirationTimestamp) {
    return parseFiniteTimestamp(tradeView.serverExpirationTimestamp);
  }
  return readCreatedExpiryMs(tradeView);
}

function readCreatedExpiryMs(tradeView: TradeView): number | null {
  const expirationSeconds = tradeView.expirationSeconds ?? 0;
  const createdAtMs = parseFiniteTimestamp(tradeView.createdAt);
  if (expirationSeconds <= 0 || createdAtMs === null) return null;
  return createdAtMs + expirationSeconds * 1_000;
}

function parseFiniteTimestamp(value: string): number | null {
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : null;
}

/** Forget the cached "sticky overlay" state. Tests only — the SPA relies
 *  on the natural lifetime of the per-instance ref across renders. */
export function resetStickyOverlayForTests(
  stickyRef: MutableRefObject<StickyOverlayState | null>,
): void {
  stickyRef.current = null;
}

/** Assert the stage-machine never regresses to `analyzing`
 *  from `active_trade`/`result` while a trade is still pending in the
 *  cache. Used by the invariant tests (and optionally callers in dev
 *  builds) to lock down the post-R261 contract.
 *
 *  Example: `assertNoStageBackslide({ prev: "active_trade", next:
 *  "analyzing", hasPendingTradeInCache: true })` throws.
 */
export function assertNoStageBackslide(params: {
  readonly prev: RobotVisualFlow["stage"];
  readonly next: RobotVisualFlow["stage"];
  readonly hasPendingTradeInCache: boolean;
}): void {
  const { prev, next, hasPendingTradeInCache } = params;
  if (!hasPendingTradeInCache) return;
  const forbiddenNext = next === "analyzing" || next === "signal";
  const isBackslide =
    (prev === "active_trade" || prev === "result") && forbiddenNext;
  if (!isBackslide) return;
  throw new Error(
    `Robot visual flow regressed from ${prev} to ${next} while a pending trade is in cache; expected sticky-overlay guard to hold the prior stage`,
  );
}

src/features/robot/components/LiveWinsTi.source:
/**
 * Tira "GANHOS AO VIVO" reproduzindo o ticker social-proof do legacy DEV.
 *
 * O DEV exibe um carrossel rolando entre o header global e o IA Core com
 * frases tipo `Bruna V. +R$ 29,22 ↑ ETH`. Sem feed real ainda, geramos uma
 * lista determinística baseada em uma seed local (hora do dia) — F.I.R.S.T
 * fica intacto: a sequência se repete em cada fresh mount.
 *
 * P0-56/R232: cada nome trader passa a vir precedido de um avatar local
 * determinístico, sem buscar /api/v2/avatars para social proof sintético.
 *
 * P0-113 (R257): pool migrou pra `lib/live-wins-pool.ts` com guard contra
 * nome/foto repetidos consecutivamente — o operador notou "Bianca A." back-
 * to-back em img41/img42 (pool antigo de 19 nomes + sequencial mod 19).
 *
 * Issue #18: visual + algorithm pass.
 *  - Single logical rail, visually duplicated (legacy parity): we render the
 *    same `entries` array through two side-by-side `TickerRail`s sharing one
 *    keyframe animation. The second copy carries `aria-hidden` and exists
 *    only so the marquee wrap-around is seamless (when rail A scrolls off
 *    the left edge, rail B is already in view; CSS keyframes restart and
 *    swap roles). There is still a single source-of-truth entries list —
 *    do NOT confuse the visual duplication with two independent feeds.
 *  - Avatar 12×12px (`object-cover` is fine at that radius — no face crop
 *    visible to the operator at iPhone widths).
 *  - Content-sized entries: drop the fixed `w-[156px]` so long names
 *    ("Valentina C.") render without `text-ellipsis`.
 */

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type RefObject,
} from "react";
import { ArrowDown, ArrowUp } from "lucide-react";
import { SocialProofAvatarImage } from "@/features/avatars";
import { formatMoney } from "../robot-page.model";
import { buildLiveWinsEntries, type LiveWinEntry } from "../lib/live-wins-pool";

// G4 (#69-followup): paridade legacy — legacy ticker had 6 entries, v2 was
// running with 12 in the same animation window, making each name scroll
// across the viewport ~2× faster than expected. Halve back to 6.
const TICKER_TOTAL_LENGTH = 6;
const TICKER_DURATION_SEQUENCE_MS = [92_000, 98_000, 104_000, 96_000] as const;
const TICKER_RESTART_MODULO = 1_000_000;
const TICKER_SCROLL_RESUME_DELAY_MS = 180;
const TICKER_VIEWPORT_STYLE: CSSProperties = {
  contain: "layout paint",
};

export function LiveWinsTicker(): React.JSX.Element {
  // R255: seed pinned per-mount via Math.random() so each refresh draws a
  // different opening name. useState keeps it stable within the session
  // (no shuffle on re-render); legacy parity comes from cycling the deck
  // freshly each page-load.
  const [seed] = useState(generateInitialSeed);
  const [runId, restartTicker] = useTickerAnimationRestart();
  const entries = useMemo(() => buildEntries(seed), [seed]);
  const durationMs = useMemo(resolveTickerDurationMs, []);
  useTickerBrowserResume(restartTicker);
  useTickerScrollResume(restartTicker);
  return (
    <div
      data-testid="live-wins-ticker"
      data-ticker-run-id={runId}
      // R300 (issue #176-3): respiração lateral aumentada em S8 (360) — antes
      // o gap entre badge "GANHOS AO VIVO" e a primeira entry parecia
      // colado. `px-2` mobile → `min-[360px]:px-2.5` dá +4px de margem sem
      // empurrar o ticker pra fora do shell.
      className="relative overflow-hidden border-y border-white/5 bg-[#0A0A0A] px-2 py-1.5 min-[360px]:px-2.5"
    >
      <div className="flex items-center gap-2 min-[360px]:gap-3">
        <TickerBadge />
        <div
          // R300: bumped text-[10px] → text-[10.5px] em min-[360px] para
          // que o ticker tenha leitura confortável no S8 sem reflowar entries.
          className="flex min-w-0 flex-1 overflow-hidden whitespace-nowrap font-mono text-[10px] leading-tight"
          style={TICKER_VIEWPORT_STYLE}
        >
          <TickerRail
            key={`visible-${runId}`}
            durationMs={durationMs}
            entries={entries}
            onAnimationCancel={restartTicker}
            runId={runId}
          />
          <TickerRail
            key={`hidden-${runId}`}
            durationMs={durationMs}
            entries={entries}
            onAnimationCancel={restartTicker}
            runId={runId}
            aria-hidden
          />
        </div>
      </div>
    </div>
  );
}

function useTickerAnimationRestart(): readonly [number, () => void] {
  const [runId, setRunId] = useState(0);
  const restartTicker = useCallback(() => {
    setRunId((current) => (current + 1) % TICKER_RESTART_MODULO);
  }, []);
  return [runId, restartTicker] as const;
}

function useTickerBrowserResume(onResume: () => void): void {
  useEffect(() => {
    const resumeIfVisible = () => {
      if (document.visibilityState !== "hidden") onResume();
    };
    document.addEventListener("visibilitychange", resumeIfVisible);
    window.addEventListener("pageshow", resumeIfVisible);
    window.addEventListener("focus", resumeIfVisible);
    return () => {
      document.removeEventListener("visibilitychange", resumeIfVisible);
      window.removeEventListener("pageshow", resumeIfVisible);
      window.removeEventListener("focus", resumeIfVisible);
    };
  }, [onResume]);
}

function useTickerScrollResume(onResume: () => void): void {
  useEffect(() => {
    let resumeTimer: number | undefined;
    const queueResume = () => {
      window.clearTimeout(resumeTimer);
      resumeTimer = window.setTimeout(onResume, TICKER_SCROLL_RESUME_DELAY_MS);
    };
    document.addEventListener("scroll", queueResume, {
      capture: true,
      passive: true,
    });
    return () => {
      window.clearTimeout(resumeTimer);
      document.removeEventListener("scroll", queueResume, true);
    };
  }, [onResume]);
}

function TickerBadge(): React.JSX.Element {
  // R300 (issue #176-3): badge bumped text-[8px] → min-[360px]:text-[9px] +
  // tracking-[0.18em] (era 0.2em). Operador no S8 viu "GANHOS AO VIVO"
  // pequeno demais comparado às entries (10px). 9px com tracking levemente
  // reduzido cabe na mesma largura visual mas com leitura melhor.
  return (
    <span className="flex shrink-0 items-center gap-1 text-[8px] font-black uppercase tracking-[0.18em] text-cyan-400/60 min-[360px]:text-[9px]">
      <span className="relative inline-flex h-1.5 w-1.5 shrink-0">
        <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-cyan-400/70" />
        <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-cyan-400" />
      </span>
      GANHOS AO VIVO
    </span>
  );
}

function TickerRail(props: {
  readonly durationMs: number;
  readonly entries: readonly LiveWinEntry[];
  readonly onAnimationCancel: () => void;
  readonly runId: number;
  readonly "aria-hidden"?: boolean;
}): React.JSX.Element {
  const railRef = useTickerAnimationCancel(props.onAnimationCancel);
  return (
    <ul
      ref={railRef}
      data-testid="live-wins-ticker-rail"
      data-ticker-run-id={props.runId}
      aria-hidden={props["aria-hidden"]}
      className="flex shrink-0 animate-[ticker-scroll_96s_linear_infinite] gap-4 pr-4 motion-reduce:animate-none"
      style={{ animationDuration: `${props.durationMs}ms` } as CSSProperties}
    >
      {props.entries.map((entry) => (
        <TickerEntry key={entry.id} entry={entry} />
      ))}
    </ul>
  );
}

function useTickerAnimationCancel(
  onAnimationCancel: () => void,
): RefObject<HTMLUListElement | null> {
  const railRef = useRef<HTMLUListElement>(null);
  useEffect(() => {
    const rail = railRef.current;
    if (!rail) return undefined;
    rail.addEventListener("animationcancel", onAnimationCancel);
    return () => rail.removeEventListener("animationcancel", onAnimationCancel);
  }, [onAnimationCancel]);
  return railRef;
}

function TickerEntry(props: {
  readonly entry: LiveWinEntry;
}): React.JSX.Element {
  const { entry } = props;
  return (
    <li
      data-testid="live-wins-ticker-entry"
      // R300 (issue #176-3): `gap-1` (4px) → `gap-1.5` (6px) min-[360px]+ —
      // dá respiração entre avatar/nome/valor/seta/asset. ArrowUp/Down e
      // avatar ganham shrink-0 explícito pra não esmagar no flex.
      className="inline-flex shrink-0 items-center gap-1 whitespace-nowrap text-white/72 min-[360px]:gap-1.5"
    >
      <SocialProofAvatarImage
        avatar={{ id: entry.avatarId, src: entry.avatarSrc }}
        size={12}
        loading="eager"
        decoding="async"
        alt=""
        className="shrink-0"
      />
      <span className="text-white/55">{entry.name}</span>
      <span className="font-bold text-emerald-300">
        +{formatMoney(entry.profitCents)}
      </span>
      {entry.direction === "CALL" ? (
        <ArrowUp className="h-3 w-3 shrink-0 text-emerald-300" />
      ) : (
        <ArrowDown className="h-3 w-3 shrink-0 text-rose-300" />
      )}
      <span className="text-white/45">{entry.asset}</span>
    </li>
  );
}

function resolveTickerDurationMs(): number {
  const seed = Math.abs(Math.floor(Date.now() / 1000));
  return (
    TICKER_DURATION_SEQUENCE_MS[seed % TICKER_DURATION_SEQUENCE_MS.length] ??
    96_000
  );
}

function buildEntries(seed: number): readonly LiveWinEntry[] {
  return buildLiveWinsEntries({ seed, count: TICKER_TOTAL_LENGTH });
}

function generateInitialSeed(): number {
  return Math.floor(Math.random() * 0x7fff_ffff);
}

src/features/robot/components/flow/useRo.source:
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type Dispatch,
  type MutableRefObject,
  type SetStateAction,
} from "react";
import {
  ROBOT_VISUAL_FLOW_CYCLE_MS,
  ROBOT_VISUAL_FLOW_TIMINGS,
  buildRobotStopVisualFlowSeed,
  buildRobotVisualFlowSeed,
  deriveRobotVisualFlow,
  getRunningStepLocation,
  resolveRobotVisualFlowSeed,
  type RobotVisualFlow,
  type RobotVisualFlowResult,
  type RobotVisualFlowSeed,
  type RobotVisualFlowSeedInput,
  type RobotVisualFlowSeedResolution,
  type RunningStepLocation,
} from "./robot-visual-flow";
import {
  applyTradeOverlay,
  resolveTradeOverlay,
  type RobotTradeOverlay,
  type RobotTradeOverlayInput,
} from "./robot-trade-flow";
import {
  reconcileStickyOverlay,
  type StickyOverlayState,
} from "./sticky-overlay-guard";
import { resolveSignalPresentedBaseFlow } from "./signal-presentation-guard";
import type { TradeView } from "@/features/trade/types";

const EMPTY_TRADE_OVERLAY: RobotTradeOverlayInput = {
  activeTrade: null,
  isPlacingTrade: false,
};

function resolveRawOverlayInput(
  input: RobotVisualFlowStateInput,
): RobotTradeOverlayInput {
  if (input.isFinanciallyStopped === true) return EMPTY_TRADE_OVERLAY;
  return input.tradeOverlay ?? EMPTY_TRADE_OVERLAY;
}

// WHY (R24-A4): the timer-driven base flow walks through all six stages on a
// 33 s cycle. Without an overlay driving real trade state, active/result are
// theater. Hold at `signal` until real activeTrade promotes those states.
const POST_SIGNAL_STAGES = new Set(["active_trade", "result"] as const);

function clampBaseFlowToSignal(
  base: RobotVisualFlow,
  seed: RobotVisualFlowSeed | null,
  nowMs: number,
): RobotVisualFlow {
  if (!POST_SIGNAL_STAGES.has(base.stage as "active_trade" | "result")) {
    return base;
  }
  if (!seed || seed.kind !== "cycle") {
    return base;
  }
  return buildHeldSignalFlow(seed, nowMs);
}

function buildHeldSignalFlow(
  seed: Extract<RobotVisualFlowSeed, { kind: "cycle" }>,
  nowMs: number,
): RobotVisualFlow {
  // Render the `signal` frame at *the current cycle's* window start. Pinning
  // it at cycle 0 (the previous behavior) meant `flow.cycleIndex` never
  // changed once the held signal stuck — `useRobotAutoTrade` then fired
  // exactly one trade per session and the bot looked broken on the second
  // round. Threading the live wall clock keeps the countdown deterministic
  // (always full window) AND lets the cycle counter advance, so each
  // wrap-around presents a fresh dedupe key to autoplay.
  const elapsedMs = Math.max(0, nowMs - seed.snapshot.startedAtMs);
  const cyclesElapsed = Math.floor(elapsedMs / ROBOT_VISUAL_FLOW_CYCLE_MS);
  const signalWindowStartMs =
    seed.snapshot.startedAtMs +
    cyclesElapsed * ROBOT_VISUAL_FLOW_CYCLE_MS +
    ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS;
  return deriveRobotVisualFlow(seed, signalWindowStartMs);
}

export type TradeSettleResult = {
  readonly profitCents: number;
  readonly sessionProfitCents: number;
};

export type RobotVisualFlowStateInput = {
  readonly strategyTitle: string;
  readonly bankPercent: number;
  readonly runtimeBalanceCents: number;
  readonly sessionProfitCents: number;
  readonly sessionStartAt: number | null;
  readonly isRunning: boolean;
  readonly isStarting: boolean;
  readonly isStopping: boolean;
  readonly isFinanciallyStopped?: boolean;
  readonly wasExplicitlyStopped: boolean;
  // Optional trade-derived inputs supplied by the caller (typically
  // robot-page-state, which already owns useActiveTrade()/usePlaceTrade()).
  // Tests and Storybook-style previews can omit this and the hook stays
  // purely timer-driven.
  readonly tradeOverlay?: RobotTradeOverlayInput;
  /** Fired once per settle event when the result overlay first appears.
   * sessionProfitCents is the running total AFTER this trade's profit. */
  readonly onTradeSettle?: (result: TradeSettleResult) => void;
};

export type RobotVisualFlowState = {
  readonly visualFlow: RobotVisualFlow;
  readonly startVisualFlow: () => void;
  readonly stopVisualFlow: () => void;
};

function useVisualFlowClock(active: boolean): number {
  const [nowMs, setNowMs] = useState(() => Date.now());

  useEffect(() => {
    if (!active) {
      return;
    }
    const refreshClock = (): void => setNowMs(Date.now());
    const intervalId = window.setInterval(
      () => setNowMs(Date.now()),
      ROBOT_VISUAL_FLOW_TIMINGS.TICK_MS,
    );
    document.addEventListener("visibilitychange", refreshClock);
    return () => {
      window.clearInterval(intervalId);
      document.removeEventListener("visibilitychange", refreshClock);
    };
  }, [active]);

  return nowMs;
}

function buildSeedInput(
  input: RobotVisualFlowStateInput,
  startedAtMs: number,
): RobotVisualFlowSeedInput {
  return {
    strategyTitle: input.strategyTitle,
    bankPercent: input.bankPercent,
    runtimeBalanceCents: input.runtimeBalanceCents,
    sessionProfitCents: input.sessionProfitCents,
    startedAtMs,
  };
}

function resolveClockActivity(
  input: RobotVisualFlowStateInput,
  seed: RobotVisualFlowSeed | null,
): boolean {
  if (input.tradeOverlay?.isPlacingTrade) {
    return true;
  }
  if (input.tradeOverlay?.activeTrade) {
    return true;
  }
  if (input.isRunning || input.isStarting) {
    return true;
  }
  return seed?.kind === "cycle";
}

function buildSeedResolutionInput(
  input: RobotVisualFlowStateInput,
  nowMs: number,
  localSeed: RobotVisualFlowSeed | null,
): RobotVisualFlowSeedResolution {
  return {
    ...buildSeedInput(input, nowMs),
    isRunning: input.isRunning,
    isStarting: input.isStarting,
    isStopping: input.isStopping,
    localSeed,
    nowMs,
    sessionStartAt: input.sessionStartAt,
    wasExplicitlyStopped: input.wasExplicitlyStopped,
  };
}

/** Drive the local visual robot flow, layering real trade state on top.
 *
 * Pre-trade stages remain timer-driven (no signal endpoint exists yet —
 * see TODO(R21-A1) in robot-visual-flow.ts). Active-trade and result stages
 * promote to real `useActiveTrade` data when available.
 *
 * Example: `const flow = useRobotVisualFlowState({ ...snapshot, isRunning })`.
 */

export function useRobotVisualFlowState(
  input: RobotVisualFlowStateInput,
): RobotVisualFlowState {
  const [localSeed, setLocalSeed] = useState<RobotVisualFlowSeed | null>(null);
  const resumeCycleRef = useRef<number | null>(null);
  const executionHoldRef = useRef(0);
  const presentedSignalCyclesRef = useRef<Map<string, number>>(new Map());
  const wasPlacingRef = useRef(false);
  const stickyOverlayRef = useRef<StickyOverlayState | null>(null);
  const rawOverlayInput = resolveRawOverlayInput(input);
  const nowMs = useVisualFlowClock(resolveClockActivity(input, localSeed));
  const overlayInput = resolveExecutionHeldOverlayInput({
    input: rawOverlayInput,
    nowMs,
    holdUntilRef: executionHoldRef,
    wasPlacingRef,
  });
  const startVisualFlow = (): void => {
    setLocalSeed(buildRobotVisualFlowSeed(buildSeedInput(input, Date.now())));
  };
  const stopVisualFlow = (): void => {
    setLocalSeed(
      buildRobotStopVisualFlowSeed({
        stoppedAtMs: Date.now(),
        reason: "manual",
      }),
    );
  };
  useFinancialStopReset({
    input,
    resumeCycleRef,
    setLocalSeed,
    stickyOverlayRef,
  });
  const resolvedSeed = resolveRobotVisualFlowSeed(
    buildSeedResolutionInput(input, nowMs, localSeed),
  );
  const rawBaseFlow = deriveRobotVisualFlow(resolvedSeed, nowMs);
  // R250's `gateOverlayForStageMinimum` was the root cause of the flicker
  // the operator hammered through R261/R262: during the cycle wrap of a
  // 60 s trade, the gate suppressed the active_trade overlay for the
  // first 6 s of every analyzing/awaiting/signal stage of cycle >= 1,
  // forcing the UI to fall back to base flow (signal/analyzing) WHILE A
  // REAL TRADE WAS STILL PENDING. The defensive sticky guard couldn't
  // recover fast enough — the operator's "transação recomeça toda hora"
  // sintoma. Removing the gate is the right fix: the sticky-overlay
  // guard alone provides the stability we need (it covers transient null
  // windows AND the cycle-wrap suppression by tracking upstream state).
  void getRunningStepLocation;
  const gatedOverlay = resolveTradeOverlay(
    overlayInput,
    input.sessionProfitCents,
    nowMs,
  );
  // R261/R262: defensive sticky-overlay gate. If a recent
  // active_trade/result overlay has gone null between polls *while a trade
  // is still believed to be in flight*, replay the last sticky overlay so
  // the flow never regresses to analyzing/awaiting_signal mid-trade. The
  // rebuilder is the same `resolveTradeOverlay` code path applied to the
  // stored TradeView so the timer keeps ticking down (R262 fixed the R261
  // freeze where the replay served a static snapshot).
  const reconciledOverlay = reconcileStickyOverlay({
    overlay: gatedOverlay,
    upstreamTradeView: rawOverlayInput.activeTrade,
    hasPendingTradeInCache: hasPendingTradeInCacheFor(rawOverlayInput),
    nowMs,
    sessionProfitCents: input.sessionProfitCents,
    stickyRef: stickyOverlayRef,
    rebuilder: rebuildStickyOverlayFromTradeView,
  });
  const overlay = useFrozenSettledResultOverlay(reconciledOverlay);
  const baseFlow = pickEffectiveBaseFlow({
    rawBaseFlow,
    seed: resolvedSeed,
    nowMs,
    overlay,
    resumeCycleRef,
    hasPendingTradeInCache: hasPendingTradeInCacheFor(rawOverlayInput),
  });
  const signalPresentedBaseFlow = resolveSignalPresentedBaseFlow({
    baseFlow,
    nowMs,
    rawBaseFlow,
    seed: resolvedSeed,
    presentedCyclesRef: presentedSignalCyclesRef,
  });
  usePostResultSeedReset({
    input,
    nowMs,
    overlay,
    resumeCycleRef,
    setLocalSeed,
  });
  useTradeSettleNotify({ overlay, onTradeSettle: input.onTradeSettle });
  return {
    visualFlow: applyTradeOverlay(signalPresentedBaseFlow, overlay),
    startVisualFlow,
    stopVisualFlow,
  };
}

function hasPendingTradeInCacheFor(input: RobotTradeOverlayInput): boolean {
  if (input.isPlacingTrade) return true;
  return input.activeTrade?.status === "pending";
}

// R262 rebuilder: feeds the stored TradeView back through resolveTradeOverlay
// at the current wall clock so the replayed active_trade/result overlay
// reflects fresh `expiresInSeconds`/`progressPercent`. This is the line of
// code that fixes the operator-reported "timer não abaixa" regression.
const rebuildStickyOverlayFromTradeView = (params: {
  readonly tradeView: TradeView;
  readonly sessionProfitCents: number;
  readonly nowMs: number;
}): RobotTradeOverlay | null =>
  resolveTradeOverlay(
    { activeTrade: params.tradeView, isPlacingTrade: false },
    params.sessionProfitCents,
    params.nowMs,
  );

function freezeSettledResultOverlay(
  overlay: RobotTradeOverlay | null,
  settledResultRef: MutableRefObject<Map<string, RobotVisualFlowResult>>,
): RobotTradeOverlay | null {
  const tradeId = overlay?.result?.tradeId;
  if (!overlay || !tradeId) return overlay;
  const settled = settledResultRef.current.get(tradeId);
  if (settled) return { ...overlay, result: settled };
  settledResultRef.current.set(tradeId, overlay.result);
  return overlay;
}

function useFrozenSettledResultOverlay(
  overlay: RobotTradeOverlay | null,
): RobotTradeOverlay | null {
  const settledResultRef = useRef<Map<string, RobotVisualFlowResult>>(
    new Map(),
  );
  return freezeSettledResultOverlay(overlay, settledResultRef);
}

const STAGE_MIN_MS: Record<RunningStepLocation["stage"], number> = {
  analyzing: ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS,
  signal: ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_MS,
  executing: ROBOT_VISUAL_FLOW_TIMINGS.EXECUTING_MS,
  active_trade: 0,
  result: 0,
};
const GATED_STAGES = new Set<RunningStepLocation["stage"]>([
  "analyzing",
  "signal",
]);

/** Suppress an active_trade/result overlay while the timer-driven flow has
 * not yet consumed the legacy 6 s minimum for the ANALISANDO/AÇÃO
 * RECOMENDADA banners. Executing is intentionally left alone —
 * `resolveExecutionHeldOverlayInput` already holds it for `EXECUTING_MS`
 * whenever placement just started.
 *
 * Only kicks in for `cycleIndex >= 1`: cycle 0 already shows the banners
 * correctly because `activeTrade` is null until placeTrade fires inside the
 * executing window. The bug the operator reported is exclusively cycle 2+:
 * a still-pending trade carried over from the previous cycle would let the
 * overlay paint `active_trade` at `stageElapsedMs=0` of the new analyzing
 * stage.
 *
 * Exported for tests so the cycle-N regression stays locked.
 */
export function gateOverlayForStageMinimum(
  overlay: RobotTradeOverlay | null,
  location: RunningStepLocation | null,
): RobotTradeOverlay | null {
  if (!overlay || !location) return overlay;
  if (overlay.stage === "executing") return overlay;
  if (location.cycleIndex === 0) return overlay;
  if (!GATED_STAGES.has(location.stage)) return overlay;
  if (location.stageElapsedMs >= STAGE_MIN_MS[location.stage]) return overlay;
  return null;
}

function resolveExecutionHeldOverlayInput(params: {
  readonly input: RobotTradeOverlayInput;
  readonly nowMs: number;
  readonly holdUntilRef: MutableRefObject<number>;
  readonly wasPlacingRef: MutableRefObject<boolean>;
}): RobotTradeOverlayInput {
  const placingStarted =
    params.input.isPlacingTrade && !params.wasPlacingRef.current;
  params.wasPlacingRef.current = params.input.isPlacingTrade;
  if (placingStarted) {
    params.holdUntilRef.current =
      params.nowMs + ROBOT_VISUAL_FLOW_TIMINGS.EXECUTING_MS;
  }
  if (
    shouldHoldExecutingOverlay(
      params.input,
      params.nowMs,
      params.holdUntilRef.current,
    )
  ) {
    return { activeTrade: null, isPlacingTrade: true };
  }
  return params.input;
}

function shouldHoldExecutingOverlay(
  input: RobotTradeOverlayInput,
  nowMs: number,
  holdUntilMs: number,
): boolean {
  if (input.isPlacingTrade) return true;
  if (nowMs >= holdUntilMs) return false;
  return input.activeTrade?.status === "pending";
}

/** Fire `onTradeSettle` once when the overlay first transitions to "result". */
function useTradeSettleNotify(params: {
  readonly overlay: RobotTradeOverlay | null;
  readonly onTradeSettle: RobotVisualFlowStateInput["onTradeSettle"];
}): void {
  const firedRef = useRef<string | null>(null);
  const result = params.overlay?.result;
  const stageIsResult = params.overlay?.stage === "result";
  useEffect(() => {
    if (!stageIsResult || !result || !params.onTradeSettle) return;
    const key =
      result.tradeId ?? `${result.profitCents}:${result.sessionProfitCents}`;
    if (firedRef.current === key) return;
    firedRef.current = key;
    params.onTradeSettle({
      profitCents: result.profitCents,
      sessionProfitCents: result.sessionProfitCents,
    });
  }, [stageIsResult, result, params]);
}

function pickEffectiveBaseFlow(params: {
  readonly rawBaseFlow: RobotVisualFlow;
  readonly seed: RobotVisualFlowSeed | null;
  readonly nowMs: number;
  readonly overlay: RobotTradeOverlay | null;
  readonly resumeCycleRef: MutableRefObject<number | null>;
  readonly hasPendingTradeInCache: boolean;
}): RobotVisualFlow {
  const {
    rawBaseFlow,
    seed,
    nowMs,
    overlay,
    resumeCycleRef,
    hasPendingTradeInCache,
  } = params;
  if (overlay) {
    if (overlay.stage === "result")
      resumeCycleRef.current = rawBaseFlow.cycleIndex + 1;
    return rawBaseFlow;
  }
  if (resumeCycleRef.current !== null && seed?.kind === "cycle") {
    return deriveRobotVisualFlow(
      seed,
      seed.snapshot.startedAtMs +
        resumeCycleRef.current * ROBOT_VISUAL_FLOW_CYCLE_MS,
    );
  }
  // Issue #191: pending real trades must never fall back to the
  // recommendation ticket. If the active-trade overlay disappears for a
  // polling frame, paint a neutral execution hold instead of `signal`.
  const pendingHoldFlow = holdPendingTradeBaseFlow({
    baseFlow: rawBaseFlow,
    hasPendingTradeInCache,
  });
  if (pendingHoldFlow !== rawBaseFlow) return pendingHoldFlow;
  return clampBaseFlowToSignal(rawBaseFlow, seed, nowMs);
}

const UNSAFE_PENDING_BASE_STAGES = new Set<RobotVisualFlow["stage"]>([
  "analyzing",
  "signal",
]);

export function holdPendingTradeBaseFlow(params: {
  readonly baseFlow: RobotVisualFlow;
  readonly hasPendingTradeInCache: boolean;
}): RobotVisualFlow {
  if (!params.hasPendingTradeInCache) return params.baseFlow;
  if (!UNSAFE_PENDING_BASE_STAGES.has(params.baseFlow.stage)) {
    return params.baseFlow;
  }
  return buildPendingTradeHoldFlow(params.baseFlow);
}

function buildPendingTradeHoldFlow(baseFlow: RobotVisualFlow): RobotVisualFlow {
  const {
    countdownSeconds: _countdownSeconds,
    progressPercent: _progressPercent,
    signal: _signal,
    signalDisplayUntilMs: _signalDisplayUntilMs,
    ...baseWithoutSignal
  } = baseFlow;
  return {
    ...baseWithoutSignal,
    stage: "executing",
    statusText: "EXECUTANDO",
    title: "Entrada em andamento",
    detail: "Confirmando operacao na corretora...",
  };
}

function useFinancialStopReset(params: {
  readonly input: RobotVisualFlowStateInput;
  readonly resumeCycleRef: MutableRefObject<number | null>;
  readonly setLocalSeed: Dispatch<SetStateAction<RobotVisualFlowSeed | null>>;
  readonly stickyOverlayRef: MutableRefObject<StickyOverlayState | null>;
}): void {
  const { input, resumeCycleRef, setLocalSeed, stickyOverlayRef } = params;
  useEffect(() => {
    if (input.isFinanciallyStopped !== true) return;
    resumeCycleRef.current = null;
    stickyOverlayRef.current = null;
    setLocalSeed(null);
  }, [
    input.isFinanciallyStopped,
    resumeCycleRef,
    setLocalSeed,
    stickyOverlayRef,
  ]);
}

function usePostResultSeedReset(params: {
  readonly input: RobotVisualFlowStateInput;
  readonly nowMs: number;
  readonly overlay: RobotTradeOverlay | null;
  readonly resumeCycleRef: MutableRefObject<number | null>;
  readonly setLocalSeed: Dispatch<SetStateAction<RobotVisualFlowSeed | null>>;
}): void {
  useLayoutEffect(() => {
    const resumeCycle = params.resumeCycleRef.current;
    if (params.overlay !== null || resumeCycle === null) return;
    const startedAtMs = params.nowMs - resumeCycle * ROBOT_VISUAL_FLOW_CYCLE_MS;
    params.setLocalSeed(
      buildRobotVisualFlowSeed(buildSeedInput(params.input, startedAtMs)),
    );
    params.resumeCycleRef.current = null;
  }, [params]);
}

