// Extracted from robot-page-state.ts so the latter stays under the 500-line cap.
// Connects the autoplay loop input builder to React state from useRobotVisualRuntime.

import { useCallback, useEffect, useRef, type RefObject } from "react";
import { usePreferences } from "@/features/preferences";
import type { PlaceTradeMutation } from "@/features/trade/hooks";
import { useCandles, type UseCandlesOptions } from "@/features/trade/hooks";
import { useRobotAutoTrade } from "./robot-auto-trade";
import { buildRobotAutoTradeInput } from "./robot-auto-trade-input";
import {
  LEGACY_ACTIVE_TRADE_COUNTBACK,
  hasCompleteRobotTradeCandles,
} from "./components/flow/robot-legacy-trade-gates";
import { buildRobotTradeAsset } from "./components/flow/robot-trade-asset";
import type { RobotTradeOverlayInput } from "./components/flow/robot-trade-flow";
import type { RobotVisualFlow } from "./components/flow/robot-visual-flow";
import type { useRobotVisualFlowState } from "./components/flow/useRobotVisualFlow";
import type { RobotVisualRuntimeParams } from "./robot-page-state";

export type RobotAutoTradeBindingArgs = {
  params: RobotVisualRuntimeParams;
  canRunLocally: boolean;
  botStopped: boolean;
  place: PlaceTradeMutation;
  tradeOverlay: RobotTradeOverlayInput;
  visual: ReturnType<typeof useRobotVisualFlowState>;
  setAutoTradeEnabled: (next: boolean) => void;
  setExecutionPending: (next: boolean) => void;
};

const EXECUTION_OBSERVATION_GRACE_MS = 8_000;
const SIGNAL_CANDLE_OPTIONS: UseCandlesOptions = {
  realtime: true,
  refetchIntervalMs: 2_000,
};
const DISABLED_SIGNAL_CANDLE_OPTIONS: UseCandlesOptions = {};

export function useRobotAutoTradeBinding(
  args: RobotAutoTradeBindingArgs,
): void {
  const preferences = usePreferences();
  const candlesReady = useSignalCandlesReady(args.visual.visualFlow);
  const signalCyclePresented = usePresentedSignalCycle(
    args.visual.visualFlow,
    args.params.queries.session.data?.session?.sessionStartAt ?? null,
  );
  const setExecutionPending = useObservedExecutionPending(args);
  useRobotAutoTrade(
    buildRobotAutoTradeInput({
      ...args.params,
      autoTradeEnabled: args.canRunLocally,
      botStopped: args.botStopped,
      candlesReady,
      onExecutionFailed: () => {
        args.setAutoTradeEnabled(false);
        args.visual.stopVisualFlow();
        args.params.queries.stop.mutate();
      },
      onExecutionPendingChange: setExecutionPending,
      place: args.place,
      preferences,
      signalCyclePresented,
      tradeOverlay: args.tradeOverlay,
      visual: args.visual,
    }),
  );
}

function useObservedExecutionPending(
  args: RobotAutoTradeBindingArgs,
): (next: boolean) => void {
  const activeTrade = args.tradeOverlay.activeTrade;
  const setExecutionPending = args.setExecutionPending;
  const clearTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => clearExecutionPendingTimer(clearTimerRef), []);
  useEffect(() => {
    if (!activeTrade) return;
    clearExecutionPendingTimer(clearTimerRef);
    setExecutionPending(false);
  }, [activeTrade, setExecutionPending]);
  return useCallback(
    (next: boolean): void => {
      clearExecutionPendingTimer(clearTimerRef);
      if (next) {
        setExecutionPending(true);
        return;
      }
      clearTimerRef.current = setTimeout(
        () => setExecutionPending(false),
        EXECUTION_OBSERVATION_GRACE_MS,
      );
    },
    [setExecutionPending],
  );
}

function clearExecutionPendingTimer(
  timerRef: RefObject<ReturnType<typeof setTimeout> | null>,
): void {
  if (timerRef.current === null) return;
  clearTimeout(timerRef.current);
  timerRef.current = null;
}

function useSignalCandlesReady(flow: RobotVisualFlow): boolean {
  const request = resolveSignalCandleRequest(flow);
  const candles = useCandles(
    request.symbol,
    "1m",
    LEGACY_ACTIVE_TRADE_COUNTBACK,
    request.options,
  );
  if (!request.required) return true;
  return hasCompleteRobotTradeCandles(candles.candles);
}

export function resolveSignalCandleRequest(flow: RobotVisualFlow): {
  readonly options: UseCandlesOptions;
  readonly required: boolean;
  readonly symbol: string;
} {
  const signal = flow.signal;
  if (!signal || !isSignalCandleStage(flow.stage)) {
    return {
      options: DISABLED_SIGNAL_CANDLE_OPTIONS,
      required: false,
      symbol: "",
    };
  }
  return {
    options: SIGNAL_CANDLE_OPTIONS,
    required: true,
    symbol: buildRobotTradeAsset(signal.asset).symbol,
  };
}

function isSignalCandleStage(stage: RobotVisualFlow["stage"]): boolean {
  return stage === "signal" || stage === "executing";
}

function usePresentedSignalCycle(
  flow: RobotVisualFlow,
  sessionStartAt: number | null,
): boolean {
  const presentedCyclesRef = useRef<Set<string>>(new Set());
  const cycleKey = `${sessionStartAt ?? "local"}:${flow.cycleIndex}`;
  useEffect(() => {
    if (flow.stage === "idle" || flow.stage === "stopped") {
      presentedCyclesRef.current.clear();
      return;
    }
    if (flow.stage === "signal" && flow.signal) {
      presentedCyclesRef.current.add(cycleKey);
    }
  }, [cycleKey, flow.signal, flow.stage]);
  return presentedCyclesRef.current.has(cycleKey);
}

