/* eslint-disable react-refresh/only-export-components */
// Minimal drop-in for @tanstack/react-query.
// Implements the API surface used in this project:
//   useQuery, useMutation, useQueryClient, QueryClient, QueryClientProvider,
//   keepPreviousData, UseQueryResult (type).
//
// Saves ~9 kB gzip vs the full TanStack library.
// Design: module-level QueryClient singleton tracks a Map<string, CacheEntry>.
// Each useQuery subscriber re-renders when its cache entry changes.
import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useRef,
  type ReactNode,
} from "react";
import { registerPollingInterval } from "./polling";
import { buildQueryResult, resolvePlaceholder } from "./result";
import { isTransientQueryError, queryRetryDelayMs } from "./transient";
export {
  useMutation,
  type MutateCallOptions,
  type UseMutationResult,
} from "./mutation";

// ── Public types ──────────────────────────────────────────────────────────────

export type QueryKey = readonly unknown[];

export interface UseQueryResult<TData = unknown> {
  data: TData | undefined;
  isLoading: boolean;
  isSuccess: boolean;
  isError: boolean;
  error: Error | null;
  refetch: () => Promise<void>;
  isRefetching: boolean;
}

interface UseQueryOptions<TData> {
  queryKey: QueryKey;
  queryFn: (context: QueryFunctionContext) => Promise<TData>;
  enabled?: boolean;
  staleTime?: number;
  gcTime?: number;
  retry?: boolean | number | QueryRetryPredicate;
  retryDelay?: QueryRetryDelay;
  networkMode?: "online" | "always" | "offlineFirst";
  refetchInterval?: number | false;
  refetchIntervalInBackground?: boolean;
  refetchOnWindowFocus?: boolean;
  placeholderData?: ((prev: unknown) => unknown) | TData;
}

export type QueryFunctionContext = { readonly signal: AbortSignal };
export type QueryRetryPredicate = (
  failureCount: number,
  error: unknown,
) => boolean;
export type QueryRetryDelay = (failureCount: number, error: unknown) => number;

/** Sentinel used as placeholderData to keep previous data during loading. */
export const keepPreviousData = (prev: unknown): unknown => prev;

// ── Cache entry ───────────────────────────────────────────────────────────────

type Subscriber = () => void;
type Status = "idle" | "loading" | "success" | "error";

interface CacheEntry {
  data: unknown;
  error: unknown;
  status: Status;
  fetchedAt: number;
  writeSeq: number;
  promise: Promise<unknown> | null;
  abortController: AbortController | null;
  subscribers: Set<Subscriber>;
  refetchTimer: ReturnType<typeof setInterval> | null;
  refetchIntervalMs: number | null;
  refetchIntervals: Map<number, number>;
  refetchQueryFn: ((context: QueryFunctionContext) => Promise<unknown>) | null;
}

interface FetchPromiseInput<TData> {
  readonly cacheKey: string;
  readonly queryFn: (context: QueryFunctionContext) => Promise<TData>;
  readonly retryCount: number;
  readonly writeSeqAtStart: number;
  readonly signal: AbortSignal;
}

interface FetchFailureInput<TData> extends FetchPromiseInput<TData> {
  readonly error: unknown;
  readonly promise: Promise<TData>;
}

function serializeKey(key: QueryKey): string {
  return JSON.stringify(key);
}

const isAbortError = (error: unknown): boolean =>
  error instanceof DOMException && error.name === "AbortError";

// ── QueryClient ───────────────────────────────────────────────────────────────

export interface QueryClientDefaultOptions {
  queries?: {
    staleTime?: number;
    gcTime?: number;
    retry?: boolean | number | QueryRetryPredicate;
    retryDelay?: QueryRetryDelay;
    networkMode?: "online" | "always" | "offlineFirst";
    refetchOnWindowFocus?: boolean;
  };
}

export class QueryClient {
  /** Exposed for test overrides. */
  readonly _cache = new Map<string, CacheEntry>();
  private readonly _defaults: QueryClientDefaultOptions;

  constructor(opts?: { defaultOptions?: QueryClientDefaultOptions }) {
    this._defaults = opts?.defaultOptions ?? {};
  }

  invalidateQueries({ queryKey }: { queryKey: QueryKey }): void {
    const prefix = JSON.stringify(queryKey).slice(0, -1); // strip trailing ]
    for (const [k, entry] of this._cache) {
      if (k.startsWith(prefix)) {
        entry.fetchedAt = 0; // mark stale
        entry.status = "idle";
        this._notify(entry);
      }
    }
  }

  setQueryData<TData>(
    queryKey: QueryKey,
    updater: TData | ((prev: TData | undefined) => TData),
  ): void {
    const k = serializeKey(queryKey);
    let entry = this._cache.get(k);
    if (!entry) {
      entry = newEntry();
      this._cache.set(k, entry);
    }
    const prev = entry.data as TData | undefined;
    entry.data =
      typeof updater === "function"
        ? (updater as (p: TData | undefined) => TData)(prev)
        : updater;
    entry.status = "success";
    entry.fetchedAt = Date.now();
    entry.writeSeq += 1;
    this._notify(entry);
  }

  async fetchQuery<TData>({
    queryKey,
    queryFn,
    staleTime = 0,
  }: {
    queryKey: QueryKey;
    queryFn: (context: QueryFunctionContext) => Promise<TData>;
    staleTime?: number;
  }): Promise<TData> {
    const k = serializeKey(queryKey);
    const entry = this._cache.get(k);
    const isStale = !entry || Date.now() - entry.fetchedAt > staleTime;
    if (!isStale && entry?.status === "success" && entry.data !== undefined) {
      return entry.data as TData;
    }
    return this._runFetch<TData>(k, queryFn);
  }

  // Issue #174: fire-and-forget warmup used by usePrefetchSecondaryTabs.
  // Mirrors TanStack's prefetchQuery semantics — resolves to void even on
  // failure so the warmup loop can `await Promise.all([...])` without aborting
  // the rest of the prefetch batch when one endpoint flakes. Honours staleTime
  // by skipping the network call when the cache entry is still fresh.
  async prefetchQuery<TData>(options: {
    queryKey: QueryKey;
    queryFn: (context: QueryFunctionContext) => Promise<TData>;
    staleTime?: number;
  }): Promise<void> {
    try {
      await this.fetchQuery(options);
    } catch {
      // Warmup must never throw — useQuery will surface real errors when the
      // tab actually mounts.
    }
  }

  getQueryData<TData>(queryKey: QueryKey): TData | undefined {
    const k = serializeKey(queryKey);
    return this._cache.get(k)?.data as TData | undefined;
  }

  clear(): void {
    for (const entry of this._cache.values()) {
      if (entry.refetchTimer) clearInterval(entry.refetchTimer);
      this._notify(entry);
    }
    this._cache.clear();
  }

  _subscribe(k: string, fn: Subscriber): () => void {
    const entry = this._ensureEntry(k);
    entry.subscribers.add(fn);
    return () => {
      entry.subscribers.delete(fn);
      if (entry.subscribers.size === 0) entry.abortController?.abort();
    };
  }

  _ensureEntry(k: string): CacheEntry {
    let entry = this._cache.get(k);
    if (!entry) {
      entry = newEntry();
      this._cache.set(k, entry);
    }
    return entry;
  }

  _notify(entry: CacheEntry): void {
    for (const sub of entry.subscribers) sub();
  }

  async _runFetch<TData>(
    k: string,
    queryFn: (context: QueryFunctionContext) => Promise<TData>,
    retryCount = 0,
  ): Promise<TData> {
    let entry = this._cache.get(k);
    if (!entry) {
      entry = newEntry();
      this._cache.set(k, entry);
    }
    if (entry.promise) return entry.promise as Promise<TData>;

    const writeSeqAtStart = entry.writeSeq;
    const abortController = new AbortController();
    entry.status = "loading";
    entry.abortController = abortController;
    this._notify(entry);

    const p = this._createFetchPromise<TData>({
      cacheKey: k,
      queryFn,
      retryCount,
      writeSeqAtStart,
      signal: abortController.signal,
    });
    entry.promise = p;
    return p;
  }

  _createFetchPromise<TData>(input: FetchPromiseInput<TData>): Promise<TData> {
    const p: Promise<TData> = input
      .queryFn({ signal: input.signal })
      .then((data) => {
        this._resolveFetchSuccess(
          input.cacheKey,
          p,
          data,
          input.writeSeqAtStart,
        );
        return data;
      })
      .catch(async (err: unknown) => {
        return this._resolveFetchFailure({ ...input, error: err, promise: p });
      });
    return p;
  }

  async _resolveFetchFailure<TData>(
    input: FetchFailureInput<TData>,
  ): Promise<TData> {
    const e = this._settledEntry(input.cacheKey, input.promise);
    if (isAbortError(input.error)) {
      this._resolveFetchAbort(e, input.writeSeqAtStart);
      throw input.error as Error;
    }
    if (e && this._shouldRetry(input) && e.writeSeq === input.writeSeqAtStart) {
      await delay(this._retryDelay(input));
      return this._runFetch<TData>(
        input.cacheKey,
        input.queryFn,
        input.retryCount + 1,
      );
    }
    this._resolveFetchError(e, input.error, input.writeSeqAtStart);
    throw input.error as Error;
  }

  _resolveFetchSuccess<TData>(
    k: string,
    p: Promise<TData>,
    data: TData,
    writeSeqAtStart: number,
  ): void {
    const e = this._settledEntry(k, p);
    if (!e || e.writeSeq !== writeSeqAtStart) return;
    e.data = data;
    e.status = "success";
    e.fetchedAt = Date.now();
    e.error = null;
    this._notify(e);
  }

  _resolveFetchError(
    e: CacheEntry | undefined,
    err: unknown,
    writeSeqAtStart: number,
  ): void {
    if (!e || e.writeSeq !== writeSeqAtStart) return;
    e.error = err;
    e.status = "error";
    e.fetchedAt = 0;
    this._notify(e);
  }

  _resolveFetchAbort(e: CacheEntry | undefined, writeSeqAtStart: number): void {
    if (!e || e.writeSeq !== writeSeqAtStart) return;
    e.error = null;
    e.status = "idle";
    e.fetchedAt = 0;
    this._notify(e);
  }

  _settledEntry<TData>(k: string, p: Promise<TData>): CacheEntry | undefined {
    const e = this._cache.get(k);
    if (e?.promise === p) {
      e.promise = null;
      e.abortController = null;
    }
    return e;
  }

  _getDefaults(): QueryClientDefaultOptions["queries"] {
    return this._defaults.queries;
  }

  private _shouldRetry(input: FetchFailureInput<unknown>): boolean {
    const retry = this._defaults.queries?.retry ?? 1;
    if (typeof retry === "function")
      return retry(input.retryCount, input.error);
    if (retry === false) return false;
    if (retry === true) return input.retryCount < 3;
    return input.retryCount < retry;
  }

  private _retryDelay(input: FetchFailureInput<unknown>): number {
    const retryDelay = this._defaults.queries?.retryDelay;
    if (retryDelay) return retryDelay(input.retryCount, input.error);
    if (isTransientQueryError(input.error)) {
      return queryRetryDelayMs(input.retryCount);
    }
    return 0;
  }
}

function newEntry(): CacheEntry {
  return {
    data: undefined,
    error: null,
    status: "idle",
    fetchedAt: 0,
    writeSeq: 0,
    promise: null,
    abortController: null,
    subscribers: new Set(),
    refetchTimer: null,
    refetchIntervalMs: null,
    refetchIntervals: new Map(),
    refetchQueryFn: null,
  };
}

// ── Context ───────────────────────────────────────────────────────────────────

const QueryClientCtx = createContext<QueryClient | null>(null);

interface QueryClientProviderProps {
  client: QueryClient;
  children?: ReactNode;
}

export function QueryClientProvider({
  client,
  children,
}: QueryClientProviderProps): React.JSX.Element {
  return (
    <QueryClientCtx.Provider value={client}>{children}</QueryClientCtx.Provider>
  );
}

export function useQueryClient(): QueryClient {
  const ctx = useContext(QueryClientCtx);
  if (!ctx)
    throw new Error("useQueryClient must be inside QueryClientProvider");
  return ctx;
}

export function useOptionalQueryClient(): QueryClient | null {
  return useContext(QueryClientCtx);
}

// ── useQuery ──────────────────────────────────────────────────────────────────

interface QueryPollingOpts {
  enabled: boolean;
  qc: QueryClient;
  k: string;
  refetchInterval: number | false | undefined;
  queryFn: (context: QueryFunctionContext) => Promise<unknown>;
}

function noop(): void {}

function delay(ms: number): Promise<void> {
  if (ms <= 0) return Promise.resolve();
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Registers one shared polling interval per query key. */
function useQueryPolling({
  enabled,
  qc,
  k,
  refetchInterval,
  queryFn,
}: QueryPollingOpts): void {
  const queryFnRef = useRef(queryFn);
  queryFnRef.current = queryFn;
  useEffect(() => {
    if (!enabled) return;
    if (!refetchInterval) return;
    const entry = qc._ensureEntry(k);
    return registerPollingInterval({
      qc,
      cacheKey: k,
      entry,
      interval: refetchInterval,
      queryFnRef,
    });
  }, [enabled, qc, k, refetchInterval]);
}

function usePollingDocumentVisible(
  refetchIntervalInBackground: boolean | undefined,
): boolean {
  const [isVisible, setIsVisible] = useState(readDocumentVisible);
  useEffect(() => {
    if (refetchIntervalInBackground !== false) return;
    const updateVisibility = () => setIsVisible(readDocumentVisible());
    updateVisibility();
    document.addEventListener("visibilitychange", updateVisibility);
    return () =>
      document.removeEventListener("visibilitychange", updateVisibility);
  }, [refetchIntervalInBackground]);
  return refetchIntervalInBackground === false ? isVisible : true;
}

function readDocumentVisible(): boolean {
  return (
    typeof document === "undefined" || document.visibilityState !== "hidden"
  );
}

function useStaleFetch(
  qc: QueryClient,
  k: string,
  opts: UseQueryOptions<unknown>,
  entry: CacheEntry | undefined,
): void {
  const queryFnRef = useRef(opts.queryFn);
  queryFnRef.current = opts.queryFn;
  const hasPromise = Boolean(entry?.promise);
  // Invalidations flip successful entries back to idle while keeping data,
  // matching TanStack's "stale but still render previous data" behavior.
  useEffect(() => {
    if (opts.enabled === false) return;
    const current = qc._cache.get(k);
    if (current?.status === "error" && opts.retry === false) return;
    if ((!current || current.status === "idle") && !current?.promise) {
      void qc
        ._runFetch(k, (context) => queryFnRef.current(context))
        .catch(noop);
    }
  }, [
    qc,
    k,
    opts.enabled,
    opts.retry,
    entry?.status,
    entry?.writeSeq,
    entry?.fetchedAt,
    hasPromise,
  ]);
}

export function useQuery<TData = unknown>(
  opts: UseQueryOptions<TData>,
): UseQueryResult<TData> {
  const qc = useQueryClient();
  const k = serializeKey(opts.queryKey);
  const [, forceUpdate] = useState(0);
  const prevDataRef = useRef<TData | undefined>(undefined);
  const [isRefetching, setIsRefetching] = useState(false);

  // Subscribe to cache notifications
  useEffect(() => qc._subscribe(k, () => forceUpdate((n) => n + 1)), [qc, k]);
  const entryForEffects = qc._cache.get(k);
  useStaleFetch(qc, k, opts as UseQueryOptions<unknown>, entryForEffects);
  const pollingDocumentVisible = usePollingDocumentVisible(
    opts.refetchIntervalInBackground,
  );
  // Always call hook; guard is inside useQueryPolling (skips when falsy interval)
  useQueryPolling({
    enabled: opts.enabled !== false && pollingDocumentVisible,
    qc,
    k,
    refetchInterval: opts.refetchInterval,
    queryFn: opts.queryFn as (
      context: QueryFunctionContext,
    ) => Promise<unknown>,
  });

  const refetch = useCallback(async (): Promise<void> => {
    setIsRefetching(true);
    try {
      const entry = qc._cache.get(k);
      if (entry) entry.fetchedAt = 0; // force stale
      await qc._runFetch(
        k,
        opts.queryFn as (context: QueryFunctionContext) => Promise<unknown>,
      );
    } catch {
      /* errors captured in cache */
    } finally {
      setIsRefetching(false);
    }
  }, [qc, k]); // eslint-disable-line react-hooks/exhaustive-deps

  const entry = qc._cache.get(k);
  const displayData = resolvePlaceholder(
    entry?.data as TData | undefined,
    opts.placeholderData as
      | ((prev: TData | undefined) => TData | undefined)
      | TData
      | undefined,
    prevDataRef,
  );
  return buildQueryResult({
    entry,
    displayData,
    refetch,
    isRefetching,
    enabled: opts.enabled !== false,
  });
}

