/**
 * LiveWinsTicker — F.I.R.S.T unit guards:
 *   Fast: render + queries only, no network.
 *   Independent: each test mocks Math.random for determinism.
 *   Repeatable: each test pins Math.random so seed is predictable.
 *   Self-validating: assertions match testid + content patterns.
 *   Timely: shipped alongside the AO VIVO ticker integration.
 *
 * P0-113 (R257): regressão que prova que o rail visível NÃO repete o
 * MESMO nome em entradas consecutivas (img41/img42).
 * R255: seed agora é por-mount (Math.random()) — testes mockam o RNG
 * para checar (a) estabilidade dentro do mount (b) sequências diferentes
 * entre dois mounts com seeds diferentes.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { act, fireEvent, render, screen } from "@testing-library/react";
import React from "react";

import { LiveWinsTicker } from "@/features/robot/components/LiveWinsTicker";

const FROZEN = new Date("2026-04-29T03:00:00.000Z").getTime();

function readNamesFromRail(rail: HTMLElement): string[] {
  const items = rail.querySelectorAll("[data-testid='live-wins-ticker-entry']");
  return Array.from(items).map((li) => {
    const name = li.querySelector("span:not([data-testid])");
    return name?.textContent ?? "";
  });
}

function readAvatarSources(): string[] {
  return Array.from(screen.getAllByTestId("avatar"), (node) => {
    const image = node.querySelector("img");
    return image?.getAttribute("src") ?? "";
  });
}

function freezeClock(): void {
  vi.useFakeTimers();
  vi.setSystemTime(FROZEN);
  setVisibilityState("visible");
  // R255: ticker seed is Math.random()-based at mount. Pin it so the
  // layout/diversity assertions stay deterministic.
  vi.spyOn(Math, "random").mockReturnValue(0.42);
}

function thawClock(): void {
  vi.useRealTimers();
  vi.restoreAllMocks();
}

function setVisibilityState(state: DocumentVisibilityState): void {
  Object.defineProperty(document, "visibilityState", {
    configurable: true,
    value: state,
  });
}

describe("LiveWinsTicker / layout", () => {
  beforeEach(freezeClock);
  afterEach(thawClock);

  it("renderiza badge GANHOS AO VIVO (P0-56) + dois rails (issue #18: single-rail duplicado)", () => {
    render(React.createElement(LiveWinsTicker));

    expect(screen.getByTestId("live-wins-ticker")).toBeInTheDocument();
    // P0-56: header passa a usar "GANHOS AO VIVO" (matching DEV).
    expect(screen.getByText(/GANHOS AO VIVO/i)).toBeInTheDocument();

    // Issue #18: 1 rail visivel + 1 cópia aria-hidden p/ loop seamless.
    const rails = screen.getAllByTestId("live-wins-ticker-rail");
    expect(rails).toHaveLength(2);
    expect(rails[1]?.getAttribute("aria-hidden")).toBe("true");
  });

  it("G4 (#69-followup): expõe 6 entries por rail (paridade legacy, ticker mais lento)", () => {
    render(React.createElement(LiveWinsTicker));

    // G4 #69-followup: operador reportou ticker rápido demais. v2 estava
    // com TICKER_TOTAL_LENGTH=12 mas legacy usa 6 — com 2× a quantidade
    // de entries no mesmo animation-duration cada nome cruza a viewport
    // 2× mais rápido. Voltamos a 6 pra paridade legacy.
    const rails = screen.getAllByTestId("live-wins-ticker-rail");
    const visible = rails[0]!;
    const items = visible.querySelectorAll("li");
    expect(items).toHaveLength(6);
    expect(visible.getAttribute("style") ?? "").toMatch(
      /animation-duration: (92000|98000|104000|96000)ms/,
    );

    items.forEach((item) => {
      expect(item.textContent || "").toMatch(/\+R\$\s*\d/);
      expect(item.textContent || "").toMatch(/(BTC|ETH)/);
    });
  });
});

describe("LiveWinsTicker / determinism + diversity", () => {
  beforeEach(freezeClock);
  afterEach(thawClock);

  it("R255: cada mount com Math.random diferente abre com pessoas diferentes", () => {
    vi.spyOn(Math, "random").mockReturnValueOnce(0.1);
    const { unmount } = render(React.createElement(LiveWinsTicker));
    const first =
      screen.getAllByTestId("live-wins-ticker-rail")[0]!.textContent ?? "";
    unmount();

    vi.spyOn(Math, "random").mockReturnValueOnce(0.9);
    render(React.createElement(LiveWinsTicker));
    const second =
      screen.getAllByTestId("live-wins-ticker-rail")[0]!.textContent ?? "";
    expect(second).not.toBe(first);
  });

  it("R255: dentro do mesmo mount o ticker é estável (sem reshuffle a cada render)", () => {
    const { rerender } = render(React.createElement(LiveWinsTicker));
    const first =
      screen.getAllByTestId("live-wins-ticker-rail")[0]!.textContent ?? "";
    rerender(React.createElement(LiveWinsTicker));
    const second =
      screen.getAllByTestId("live-wins-ticker-rail")[0]!.textContent ?? "";
    expect(second).toBe(first);
  });

  it("não exibe o mesmo nome em entradas consecutivas (regressão P0-113)", () => {
    render(React.createElement(LiveWinsTicker));
    const visible = screen.getAllByTestId("live-wins-ticker-rail")[0]!;
    const names = readNamesFromRail(visible);
    // Issue #18: single-rail = 12 entries.
    expect(names).toHaveLength(6);
    for (let i = 1; i < names.length; i += 1) {
      expect(names[i]).not.toBe(names[i - 1]);
    }
  });

  it("G4 (#69-followup): renderiza 6 avatars únicos por rail (legacy parity)", () => {
    render(React.createElement(LiveWinsTicker));
    const sources = readAvatarSources();
    // G4: two rails × 6 entries = 12 nodes; uniq deck has 6.
    expect(sources).toHaveLength(12);
    expect(new Set(sources).size).toBe(6);
    sources.forEach((src) => expect(src).toMatch(/^\/avatars\//));
  });

  it("issue #18: entries não usam mais width fixo w-[156px]", () => {
    render(React.createElement(LiveWinsTicker));
    const items = screen.getAllByTestId("live-wins-ticker-entry");
    items.forEach((item) => {
      expect(item.className).not.toMatch(/w-\[\d+px\]/);
      // inline-flex shrink-0 are the issue-18 layout primitives.
      expect(item.className).toMatch(/inline-flex/);
      expect(item.className).toMatch(/shrink-0/);
    });
  });

  it("issue #18: avatar img renderiza em 12×12px (nativePx = 24 com PIXEL_DENSITY=2)", () => {
    render(React.createElement(LiveWinsTicker));
    const imgs = screen
      .getAllByTestId("avatar")
      .map((node) => node.querySelector("img"));
    imgs.forEach((img) => {
      expect(img).not.toBeNull();
      // SocialProofAvatarImage multiplies size×PIXEL_DENSITY for retina.
      expect(img?.getAttribute("width")).toBe("24");
      expect(img?.getAttribute("height")).toBe("24");
    });
  });

  it("issue #18: rail aplica motion-reduce:animate-none", () => {
    render(React.createElement(LiveWinsTicker));
    const rails = screen.getAllByTestId("live-wins-ticker-rail");
    rails.forEach((rail) => {
      expect(rail.className).toMatch(/motion-reduce:animate-none/);
    });
  });

  // R2 mutation guard: both rails share ONE source-of-truth entries list.
  // The visible rail and the aria-hidden duplicate must render the SAME
  // names in the SAME order (legacy seamless marquee parity). A mutation
  // that calls `buildEntries(seed)` per-rail instead of once at the parent
  // (or that introduces a per-rail useMemo) would produce two divergent
  // sequences and break the loop illusion. Pin order + length identity.
  it("R2: visible rail and aria-hidden rail render identical name order", () => {
    render(React.createElement(LiveWinsTicker));
    const rails = screen.getAllByTestId("live-wins-ticker-rail");
    expect(rails).toHaveLength(2);
    const visibleNames = readNamesFromRail(rails[0]!);
    const hiddenNames = readNamesFromRail(rails[1]!);
    // G4 (#69-followup): legacy parity halved entries 12 → 6.
    expect(visibleNames).toHaveLength(6);
    expect(hiddenNames).toEqual(visibleNames);
  });

  it("issue #192: remonta rails quando o WebView cancela a animação", () => {
    render(React.createElement(LiveWinsTicker));
    expect(screen.getByTestId("live-wins-ticker")).toHaveAttribute(
      "data-ticker-run-id",
      "0",
    );

    const rail = screen.getAllByTestId("live-wins-ticker-rail")[0]!;
    fireEvent(rail, new Event("animationcancel"));

    expect(screen.getByTestId("live-wins-ticker")).toHaveAttribute(
      "data-ticker-run-id",
      "1",
    );
    expect(screen.getAllByTestId("live-wins-ticker-rail")[0]).not.toBe(rail);
    expect(screen.getAllByTestId("live-wins-ticker-rail")[0]).toHaveAttribute(
      "data-ticker-run-id",
      "1",
    );
  });

  it("issue #192: retoma ticker depois de scroll e retorno de aba", () => {
    render(React.createElement(LiveWinsTicker));
    expect(screen.getByTestId("live-wins-ticker")).toHaveAttribute(
      "data-ticker-run-id",
      "0",
    );

    fireEvent.scroll(document);
    expect(screen.getByTestId("live-wins-ticker")).toHaveAttribute(
      "data-ticker-run-id",
      "0",
    );
    act(() => vi.advanceTimersByTime(181));
    expect(screen.getByTestId("live-wins-ticker")).toHaveAttribute(
      "data-ticker-run-id",
      "1",
    );

    setVisibilityState("hidden");
    fireEvent(document, new Event("visibilitychange"));
    expect(screen.getByTestId("live-wins-ticker")).toHaveAttribute(
      "data-ticker-run-id",
      "1",
    );

    setVisibilityState("visible");
    fireEvent(document, new Event("visibilitychange"));
    expect(screen.getByTestId("live-wins-ticker")).toHaveAttribute(
      "data-ticker-run-id",
      "2",
    );
  });

  it("issue #192: retoma ticker em pageshow e focus", () => {
    render(React.createElement(LiveWinsTicker));

    fireEvent(window, new Event("pageshow"));
    expect(screen.getByTestId("live-wins-ticker")).toHaveAttribute(
      "data-ticker-run-id",
      "1",
    );

    fireEvent(window, new Event("focus"));
    expect(screen.getByTestId("live-wins-ticker")).toHaveAttribute(
      "data-ticker-run-id",
      "2",
    );
  });

  it("issue #192: limpa listeners de retomada ao desmontar", () => {
    const documentRemoveSpy = vi.spyOn(document, "removeEventListener");
    const windowRemoveSpy = vi.spyOn(window, "removeEventListener");
    const { unmount } = render(React.createElement(LiveWinsTicker));

    unmount();

    expect(documentRemoveSpy).toHaveBeenCalledWith(
      "visibilitychange",
      expect.any(Function),
    );
    expect(documentRemoveSpy).toHaveBeenCalledWith(
      "scroll",
      expect.any(Function),
      true,
    );
    expect(windowRemoveSpy).toHaveBeenCalledWith(
      "pageshow",
      expect.any(Function),
    );
    expect(windowRemoveSpy).toHaveBeenCalledWith("focus", expect.any(Function));
  });
});

