import {
  act,
  cleanup,
  render,
  renderHook,
  screen,
} from "@testing-library/react";
import type { ReactElement } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { QueryClient, QueryClientProvider } from "@/lib/query";
import { tradeKeys } from "@/features/trade/keys";
import { RobotFlowStageRenderer } from "./RobotFlowStageRenderer";
import {
  ROBOT_VISUAL_FLOW_CYCLE_MS,
  ROBOT_VISUAL_FLOW_TIMINGS,
  buildRobotVisualFlowSeed,
  deriveRobotVisualFlow,
  pickSignalAsset,
  resolveRobotVisualFlowSeed,
  type RobotVisualFlowSeed,
} from "./robot-visual-flow";
import {
  ROBOT_RESULT_COOLDOWN_MS,
  resetSettledObservationsForTests,
  resolveTradeOverlay,
  type RobotTradeOverlayInput,
} from "./robot-trade-flow";
import type { TradeView } from "@/features/trade/types";
import {
  holdPendingTradeBaseFlow,
  useRobotVisualFlowState,
  type RobotVisualFlowStateInput,
} from "./useRobotVisualFlow";

afterEach(() => {
  vi.useRealTimers();
  vi.unstubAllGlobals();
});

const visualInput: RobotVisualFlowStateInput = {
  strategyTitle: "Moderado",
  bankPercent: 4,
  runtimeBalanceCents: 100_000,
  sessionProfitCents: 0,
  sessionStartAt: null,
  isRunning: false,
  isStarting: false,
  isStopping: false,
  wasExplicitlyStopped: false,
};

function buildVisualSeed(): RobotVisualFlowSeed {
  return buildRobotVisualFlowSeed({ ...visualInput, startedAtMs: 1_000 });
}

describe("robot visual flow model", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("derives the complete trade-flow stages deterministically", () => {
    const seed = buildVisualSeed();
    const signalAtMs = 1_000 + ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS;
    const executingAtMs = signalAtMs + ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_MS;
    const nextCycleAtMs =
      executingAtMs + ROBOT_VISUAL_FLOW_TIMINGS.EXECUTING_MS;

    expect(deriveRobotVisualFlow(seed, 1_000).stage).toBe("analyzing");
    expect(deriveRobotVisualFlow(seed, signalAtMs).stage).toBe("signal");
    expect(deriveRobotVisualFlow(seed, executingAtMs).stage).toBe("executing");
    expect(deriveRobotVisualFlow(seed, nextCycleAtMs).stage).toBe("analyzing");
  });

  // #109: the analyzing window must NEVER carry a `signal` field. If it does,
  // SignalStageContent paints the AÇÃO RECOMENDADA ticket between the neural
  // stage finishing and the React re-render, causing a 1-frame flicker the
  // operator reported on 2026-05-25.
  it("#109: derived analyzing frames never expose a signal payload", () => {
    const seed = buildVisualSeed();
    const startMs = 1_000;
    const samples = [0, 100, 1_000, 3_000, 5_000, 5_999];
    for (const offset of samples) {
      const flow = deriveRobotVisualFlow(seed, startMs + offset);
      expect(flow.stage).toBe("analyzing");
      expect(flow.signal).toBeUndefined();
    }
  });

  it("exposes the wall-clock deadline for the signal banner", () => {
    const seed = buildVisualSeed();
    const signalAtMs = 1_000 + ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS;
    const flow = deriveRobotVisualFlow(seed, signalAtMs + 1_000);

    expect(flow.stage).toBe("signal");
    expect(flow.detail).toBe("Acao recomendada: VENDA.");
    expect(ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_TRADE_SUBMIT_DELAY_MS).toBe(
      ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_MS,
    );
    expect(flow.signalDisplayUntilMs).toBe(
      signalAtMs + ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_TRADE_SUBMIT_DELAY_MS,
    );
  });

  it("varies the fallback signal asset between consecutive cycles", () => {
    const seed = buildVisualSeed();
    const cycle0SignalAtMs = 1_000 + ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS;
    const cycle1SignalAtMs = cycle0SignalAtMs + ROBOT_VISUAL_FLOW_CYCLE_MS;

    expect(deriveRobotVisualFlow(seed, cycle0SignalAtMs).signal?.asset).toBe(
      "BTCUSDT",
    );
    expect(deriveRobotVisualFlow(seed, cycle1SignalAtMs).signal?.asset).toBe(
      "ETHUSDT",
    );
  });

  it("keeps recommended action visible for the full 6 seconds before executing", () => {
    const seed = buildVisualSeed();
    const signalAtMs = 1_000 + ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS;
    const lastSignalFrame = deriveRobotVisualFlow(
      seed,
      signalAtMs + ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_MS - 1,
    );
    const afterSignalDelay = deriveRobotVisualFlow(
      seed,
      signalAtMs + ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_MS,
    );

    expect(lastSignalFrame.stage).toBe("signal");
    expect(lastSignalFrame.signal?.direction).toBe("PUT");
    expect(lastSignalFrame.detail).toContain("VENDA");
    expect(lastSignalFrame.signalDisplayUntilMs).toBe(signalAtMs + 6_000);
    expect(afterSignalDelay.stage).toBe("executing");
  });

  // G5 (#69-followup): every running stage must carry `signalDisplayUntilMs`
  // so `isSignalDisplayPending` blocks autoplay during the analyzing window
  // of each new cycle (not only cycle 0). Operator: AÇÃO RECOMENDADA was
  // missing on trades after the first because the gate opened too early.
  it("G5: analyzing flow on cycle 2 carries signalDisplayUntilMs", () => {
    const seed = buildVisualSeed();
    // Cycle 2 analyzing starts at startedAtMs + 2 * CYCLE_MS.
    const cycle2AnalyzingAtMs = 1_000 + 2 * 18_000 + 1_000; // 1s into analyzing of cycle 2
    const flow = deriveRobotVisualFlow(seed, cycle2AnalyzingAtMs);
    expect(flow.stage).toBe("analyzing");
    expect(flow.cycleIndex).toBe(2);
    expect(flow.signalDisplayUntilMs).toBe(
      1_000 +
        2 * 18_000 +
        ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS +
        ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_TRADE_SUBMIT_DELAY_MS,
    );
    expect(flow.signalDisplayUntilMs).toBeGreaterThan(cycle2AnalyzingAtMs);
  });

  it("G5 (refined): executing flow leaves signalDisplayUntilMs UNDEFINED so autoplay can fire", () => {
    // Operator hit a regression where executing got stuck in a loop —
    // the previous G5 implementation populated `signalDisplayUntilMs`
    // on every running stage, and any tick alignment quirk where
    // `nowMs < untilMs` at the boundary made `isSignalDisplayPending`
    // swallow the trade attempt. Executing MUST stay deadline-less so
    // the gate falls through to the execution-stage check and fires.
    const seed = buildVisualSeed();
    const cycle2ExecutingAtMs =
      1_000 +
      2 * 18_000 +
      ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS +
      ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_MS +
      1_000;
    const flow = deriveRobotVisualFlow(seed, cycle2ExecutingAtMs);
    expect(flow.stage).toBe("executing");
    expect(flow.signalDisplayUntilMs).toBeUndefined();
  });

  it("prefers stop visual state over a local running cycle", () => {
    const seed = resolveRobotVisualFlowSeed({
      ...visualInput,
      startedAtMs: 1_000,
      localSeed: buildVisualSeed(),
      nowMs: 2_000,
      isStopping: true,
    });

    expect(deriveRobotVisualFlow(seed, 2_000).stage).toBe("stopped");
  });
});

