function renderWithQuery(ui: ReactElement): void {
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  client.setQueryData(tradeKeys.active(), null);
  client.setQueryData(tradeKeys.history(200, 0), { items: [], total: 0 });
  client.setQueryData(
    tradeKeys.candles("BTCUSDT", 60, 50, true),
    testCandles(50),
  );
  render(<QueryClientProvider client={client}>{ui}</QueryClientProvider>);
}

function testCandles(count: number) {
  return Array.from({ length: count }, (_, index) => {
    const close = 64_000 + index;
    return {
      close,
      high: close + 10,
      low: close - 10,
      open: close - 4,
      time: 1_700_000_000 + index * 60,
      value: close,
    };
  });
}

