  it("issue #191: holds analyzing but leaves executing unchanged", () => {
    const seed = buildVisualSeed();
    const analyzingFlow = deriveRobotVisualFlow(seed, 1_000 + 500);
    const executingFlow = deriveRobotVisualFlow(
      seed,
      1_000 +
        ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS +
        ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_MS +
        1_000,
    );

    expect(
      holdPendingTradeBaseFlow({
        baseFlow: analyzingFlow,
        hasPendingTradeInCache: true,
      }).stage,
    ).toBe("executing");
    expect(
      holdPendingTradeBaseFlow({
        baseFlow: executingFlow,
        hasPendingTradeInCache: true,
      }),
    ).toBe(executingFlow);
  });

  it("does not alter signal frames without a pending trade", () => {
    const signalFlow = deriveRobotVisualFlow(
      buildVisualSeed(),
      1_000 + ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS + 1_000,
    );

    expect(
      holdPendingTradeBaseFlow({
        baseFlow: signalFlow,
        hasPendingTradeInCache: false,
      }),
    ).toBe(signalFlow);
  });
});

function executingElapsedMs(): number {
  return (
    ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS +
    ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_MS +
    1_000
  );
}

function activeTradeElapsedMs(): number {
  return executingElapsedMs() + ROBOT_VISUAL_FLOW_TIMINGS.EXECUTING_MS;
}

describe("robot visual flow signal asset", () => {
  it("derives a deterministic asset per session start (no Date.now flicker)", () => {
    expect(pickSignalAsset(1_000)).toBe("BTCUSDT");
    expect(pickSignalAsset(1_001)).toBe("ETHUSDT");
    expect(pickSignalAsset(1_002)).toBe("BTCUSDT");
    // Same seed → same asset across calls (stable per render).
    expect(pickSignalAsset(1_000)).toBe(pickSignalAsset(1_000));
  });

  it("clamps non-finite or negative seeds to a safe default asset", () => {
    expect(pickSignalAsset(Number.NaN)).toBe("BTCUSDT");
    expect(pickSignalAsset(-1)).toBe("BTCUSDT");
  });
});

// C-6 (#69) F-recommended-action: legacy parity requires AÇÃO RECOMENDADA
// to appear during the signal stage of EVERY trade cycle (not only the first).
// Previously no multi-cycle test exercised the post-result resume — only the
// first signal stage was covered.
describe("recommended action per trade cycle (legacy parity)", () => {
  it("re-enters analyzing → signal with a signal field after each trade settles", () => {
    vi.useFakeTimers();
    const sessionStart = 2_000_000_000_000;
    vi.setSystemTime(new Date(sessionStart));
    resetSettledObservationsForTests();

    const pending = buildPendingTrade();
    const settled = buildPendingTrade({
      id: "trade-1",
      status: "win",
      payoutCents: 800,
      settledAt: new Date(sessionStart + 5_000).toISOString(),
    });
    const pending2 = buildPendingTrade({ id: "trade-2", tradeId: "ext-2" });
    const settled2 = buildPendingTrade({
      id: "trade-2",
      tradeId: "ext-2",
      status: "win",
      payoutCents: 700,
      settledAt: new Date(sessionStart + 20_000).toISOString(),
    });

    const { result, rerender } = renderHook(
      (input: RobotVisualFlowStateInput) => useRobotVisualFlowState(input),
      {
        initialProps: {
          ...overlayBaseInput,
          sessionStartAt: sessionStart,
          tradeOverlay: { activeTrade: null, isPlacingTrade: false },
        } as RobotVisualFlowStateInput,
      },
    );
    act(() => result.current.startVisualFlow());

    rerender({
      ...overlayBaseInput,
      sessionStartAt: sessionStart,
      tradeOverlay: { activeTrade: pending, isPlacingTrade: false },
    });
    expect(result.current.visualFlow.stage).toBe("active_trade");

    rerender({
      ...overlayBaseInput,
      sessionStartAt: sessionStart,
      tradeOverlay: { activeTrade: settled, isPlacingTrade: false },
    });
    expect(result.current.visualFlow.stage).toBe("result");

    act(() => {
      vi.advanceTimersByTime(ROBOT_RESULT_COOLDOWN_MS + 100);
    });
    rerender({
      ...overlayBaseInput,
      sessionStartAt: sessionStart,
      tradeOverlay: { activeTrade: null, isPlacingTrade: false },
    });

    // Cycle 2 should now be in progress. Advance to the signal window
    // (analyzing 6s → signal 6s starts at t=6s of the resumed cycle).
    act(() => {
      vi.advanceTimersByTime(ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS + 1_000);
    });
    rerender({
      ...overlayBaseInput,
      sessionStartAt: sessionStart,
      tradeOverlay: { activeTrade: null, isPlacingTrade: false },
    });

    expect(result.current.visualFlow.stage).toBe("signal");
    expect(result.current.visualFlow.signal).toBeDefined();
    expect(result.current.visualFlow.detail).toContain("Acao recomendada");

    rerender({
      ...overlayBaseInput,
      sessionStartAt: sessionStart,
      tradeOverlay: { activeTrade: pending2, isPlacingTrade: false },
    });
    expect(result.current.visualFlow.stage).toBe("active_trade");

    rerender({
      ...overlayBaseInput,
      sessionStartAt: sessionStart,
      tradeOverlay: { activeTrade: settled2, isPlacingTrade: false },
    });
    expect(result.current.visualFlow.stage).toBe("result");

    act(() => {
      vi.advanceTimersByTime(ROBOT_RESULT_COOLDOWN_MS + 100);
    });
    rerender({
      ...overlayBaseInput,
      sessionStartAt: sessionStart,
      tradeOverlay: { activeTrade: null, isPlacingTrade: false },
    });
    act(() => {
      vi.advanceTimersByTime(ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS + 1_000);
    });
    rerender({
      ...overlayBaseInput,
      sessionStartAt: sessionStart,
      tradeOverlay: { activeTrade: null, isPlacingTrade: false },
    });

    expect(result.current.visualFlow.stage).toBe("signal");
    expect(result.current.visualFlow.signal).toBeDefined();
    expect(result.current.visualFlow.detail).toContain("Acao recomendada");
    vi.useRealTimers();
  });
});

// R249: active-trade card mirrors the current IA Core stage budget and leaves
// enough vertical room for the chart to fill the card without a dead band.
describe("R249 active-trade card dimensions", () => {
  it("renders robot-legacy-trade-card with legacy adaptive height", async () => {
    const activeFlow = buildActiveTradeVisualFlow();
    renderWithQuery(<RobotFlowStageRenderer flow={activeFlow} />);

    const card = await screen.findByTestId("robot-legacy-trade-card");
    expect(card.className).toContain("h-[min(560px");
    expect(card.className).toContain("min-h-[280px]");
    expect(card.className).toContain("xl:h-[568px]");
    expect(card.className).not.toContain("h-[580px]");
  });
});

