import { act, renderHook } from "@testing-library/react";
import type { ReactNode } from "react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { QueryClient, QueryClientProvider } from "@/lib/query";
import {
  buildSaoPauloTodayStatsRange,
  useRobotPageState,
} from "./robot-page-state";
import { LEGACY_ACTIVE_TRADE_COUNTBACK } from "./components/flow/robot-legacy-trade-gates";
import { ROBOT_VISUAL_FLOW_TIMINGS } from "./components/flow/robot-visual-flow";
import type * as RobotApi from "./api";
import type { BotSessionState } from "./api";
import {
  buildAllowedSubscriptionDashboard,
  buildBotSessionStateWithLimits,
  buildCancelledTrade,
  buildDuplicateCandles,
  buildLossTrade,
  buildMutationStub,
  buildNoSessionState,
  buildPendingTrade,
  buildPlaceMutation,
  buildQueryResult,
  buildRenderableCandles,
  buildRobotSessionState,
  buildRunningBotSession,
  buildSettledTrade,
  buildSubscriptionDashboard,
  buildWinTrade,
} from "./robot-page-state.test.builders";

const hookMocks = vi.hoisted(() => ({
  useActiveTrade: vi.fn(),
  useBalance: vi.fn(),
  useBotSessionState: vi.fn(),
  useCandles: vi.fn(),
  useDailyTradeStats: vi.fn(),
  usePlaceTrade: vi.fn(),
  useTradeStream: vi.fn(),
  useRobotAutoTrade: vi.fn(),
  resetRobotAutoTradeDedupe: vi.fn(),
  hardStopRobotAutoTradeRuntime: vi.fn(),
  useRobotIntel: vi.fn(),
  useStartBotSession: vi.fn(),
  useStopBotSession: vi.fn(),
  useSubscriptionDashboard: vi.fn(),
  useTradeHistory: vi.fn(),
  patchBotSessionRuntime: vi.fn(() => Promise.resolve()),
}));

vi.mock("@/features/dashboard/hooks", () => ({
  useBalance: hookMocks.useBalance,
  useRobotIntel: hookMocks.useRobotIntel,
  useSubscriptionDashboard: hookMocks.useSubscriptionDashboard,
}));

vi.mock("@/features/trade/hooks", () => ({
  useActiveTrade: hookMocks.useActiveTrade,
  useCandles: hookMocks.useCandles,
  useDailyTradeStats: hookMocks.useDailyTradeStats,
  usePlaceTrade: hookMocks.usePlaceTrade,
  useTradeHistory: hookMocks.useTradeHistory,
  useTradeStream: hookMocks.useTradeStream,
}));

vi.mock("./hooks", () => ({
  useBotSessionState: hookMocks.useBotSessionState,
  useStartBotSession: hookMocks.useStartBotSession,
  useStopBotSession: hookMocks.useStopBotSession,
}));

vi.mock("./robot-auto-trade", () => ({
  hardStopRobotAutoTradeRuntime: hookMocks.hardStopRobotAutoTradeRuntime,
  resetRobotAutoTradeDedupe: hookMocks.resetRobotAutoTradeDedupe,
  useRobotAutoTrade: hookMocks.useRobotAutoTrade,
}));

vi.mock("./api", async (importOriginal) => {
  const original = await importOriginal<typeof RobotApi>();
  return {
    ...original,
    patchBotSessionRuntime: hookMocks.patchBotSessionRuntime,
  };
});

describe("useRobotPageState trade overlay", () => {
  beforeEach(() => {
    hookMocks.useRobotAutoTrade.mockClear();
    hookMocks.useTradeStream.mockClear();
    hookMocks.hardStopRobotAutoTradeRuntime.mockClear();
    hookMocks.resetRobotAutoTradeDedupe.mockClear();
    mockRobotPageQueries(buildRobotSessionState());
    hookMocks.useActiveTrade.mockReturnValue({
      trade: null,
      isLoading: false,
      isError: false,
    });
    hookMocks.usePlaceTrade.mockReturnValue(
      buildPlaceMutation({ data: undefined, isPending: false }),
    );
  });

  it("shows POST-created pending trade while active-trade polling is delayed", () => {
    const postedTrade = buildPendingTrade({ id: "posted-trade" });
    hookMocks.usePlaceTrade.mockReturnValue(
      buildPlaceMutation({ data: postedTrade, isPending: false }),
    );

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.visualFlow.stage).toBe("active_trade");
    expect(result.current.visualFlow.trade?.asset).toBe("BTCUSDT");
    expect(hookMocks.useRobotAutoTrade).toHaveBeenCalledWith(
      expect.objectContaining({ activeTrade: postedTrade }),
    );
  });

  it("opens the trade stream on the robot page for settlement events", () => {
    renderHook(() => useRobotPageState(), { wrapper: TestQueryWrapper });
    expect(hookMocks.useTradeStream).toHaveBeenCalled();
  });

  it("does not synthesize a trade when no active trade or POST result exists", () => {
    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.visualFlow.stage).not.toBe("active_trade");
    expect(result.current.visualFlow.trade).toBeUndefined();
  });

  it("keeps execution overlay after POST success until a trade is observed", () => {
    vi.useFakeTimers();
    try {
      const { result } = renderHook(() => useRobotPageState(), {
        wrapper: TestQueryWrapper,
      });
      const input = hookMocks.useRobotAutoTrade.mock.lastCall?.[0];

      act(() => input.onExecutionPendingChange(true));
      expect(result.current.visualFlow.stage).toBe("executing");

      act(() => input.onExecutionPendingChange(false));
      act(() => vi.advanceTimersByTime(7_999));
      expect(result.current.visualFlow.stage).toBe("executing");
    } finally {
      vi.useRealTimers();
    }
  });

  it("hydrates a pending trade from recent history when active polling misses it", () => {
    const historyPending = buildPendingTrade({ id: "history-pending" });
    hookMocks.useTradeHistory.mockReturnValue({
      page: { items: [historyPending] },
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.visualFlow.stage).toBe("active_trade");
    expect(hookMocks.useRobotAutoTrade).toHaveBeenCalledWith(
      expect.objectContaining({ activeTrade: historyPending }),
    );
  });

  it("ignores stale pending history when active polling returns null after reentry", () => {
    const staleHistoryPending = buildPendingTrade({
      id: "history-stale-pending",
      createdAt: new Date(Date.now() - 4 * 60 * 60_000).toISOString(),
      expirationSeconds: 60,
      expirationTimestamp: Date.now() - 3 * 60 * 60_000,
    });
    hookMocks.useTradeHistory.mockReturnValue({
      page: { items: [staleHistoryPending] },
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.visualFlow.stage).not.toBe("active_trade");
    expect(result.current.visualFlow.trade).toBeUndefined();
    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ activeTrade: null }),
    );
  });

  it("auto-arms a backend-running session after login without a pending trade", () => {
    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.isRunning).toBe(true);
    expect(result.current.visualFlow.stage).not.toBe("idle");
    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ activeTrade: null, enabled: true }),
    );
  });

  it("R259/R262: stale session (updatedAt > 15 min ago) does not arm auto-trade", () => {
    // Build a session whose backend `updatedAt` is 20 minutes old — backend
    // should have soft-stopped already; this guard is the frontend belt-and-
    // suspenders. R262: gate now keys off `updatedAt` (refreshed on every
    // settle) so an actively-trading session never trips the threshold.
    mockRobotPageQueries({
      session: {
        ...buildRunningBotSession(),
        updatedAt: Date.now() - 20 * 60_000,
      },
      wasExplicitlyStopped: false,
    });

    renderHook(() => useRobotPageState(), { wrapper: TestQueryWrapper });

    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ enabled: false }),
    );
  });

  it("R262: actively-trading session with recent updatedAt stays auto-armed past 5 min mark", () => {
    // Reproduces the operator-reported bug: bot fires 2 trades, then stops
    // because `sessionStartAt` aged past 2 min. With the R262 fix keyed on
    // `updatedAt`, an active session whose backend settle just bumped
    // `updatedAt` stays armed indefinitely.
    mockRobotPageQueries({
      session: {
        ...buildRunningBotSession(),
        sessionStartAt: Date.now() - 6 * 60_000, // 6 min since INICIAR
        updatedAt: Date.now() - 30_000, // backend settled 30 s ago
      },
      wasExplicitlyStopped: false,
    });

    renderHook(() => useRobotPageState(), { wrapper: TestQueryWrapper });

    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ enabled: true }),
    );
  });

  it("does not arm auto trade when signal candles collapse below the legacy count", () => {
    hookMocks.useCandles.mockReturnValue({
      candles: buildDuplicateCandles(),
      isLoading: false,
      isError: false,
    });

    renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ candlesReady: false }),
    );
  });

  it("issue #190: does not start signal-candle polling during analyzing", () => {
    vi.useFakeTimers();
    try {
      const nowMs = 2_200_000_000_000;
      vi.setSystemTime(nowMs);
      mockRobotPageQueries({
        session: {
          ...buildRunningBotSession(),
          sessionStartAt: nowMs - 1_000,
        },
        wasExplicitlyStopped: false,
      });
      hookMocks.useCandles.mockReturnValue({
        candles: [],
        isLoading: false,
        isError: false,
      });

      renderHook(() => useRobotPageState(), { wrapper: TestQueryWrapper });

      expect(hookMocks.useCandles).toHaveBeenLastCalledWith(
        "",
        "1m",
        LEGACY_ACTIVE_TRADE_COUNTBACK,
        {},
      );
      expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
        expect.objectContaining({ candlesReady: true }),
      );
    } finally {
      vi.useRealTimers();
    }
  });

  it("issue #190: ignores active-trade signal payload for candle polling", () => {
    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildPendingTrade({ id: "active-trade-poll-gate" }),
      isLoading: false,
      isError: false,
    });
    hookMocks.useCandles.mockReturnValue({
      candles: [],
      isLoading: false,
      isError: false,
    });

    renderHook(() => useRobotPageState(), { wrapper: TestQueryWrapper });

    expect(hookMocks.useCandles).toHaveBeenLastCalledWith(
      "",
      "1m",
      LEGACY_ACTIVE_TRADE_COUNTBACK,
      {},
    );
    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ candlesReady: true }),
    );
  });

  it("issue #190: starts realtime signal-candle polling only on signal", () => {
    vi.useFakeTimers();
    try {
      const nowMs = 2_200_000_000_000;
      vi.setSystemTime(nowMs);
      mockRobotPageQueries({
        session: {
          ...buildRunningBotSession(),
          sessionStartAt:
            nowMs - ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS - 1_000,
        },
        wasExplicitlyStopped: false,
      });

      renderHook(() => useRobotPageState(), { wrapper: TestQueryWrapper });
      const lastCall = hookMocks.useCandles.mock.lastCall;

      expect(lastCall?.[0]).toMatch(/USDT$/);
      expect(lastCall?.[1]).toBe("1m");
      expect(lastCall?.[2]).toBe(LEGACY_ACTIVE_TRADE_COUNTBACK);
      expect(lastCall?.[3]).toEqual({
        realtime: true,
        refetchIntervalMs: 2_000,
      });
    } finally {
      vi.useRealTimers();
    }
  });

  it("does not arm auto trade when execution is held and signal candles collapse", () => {
    const executingElapsedMs =
      ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS +
      ROBOT_VISUAL_FLOW_TIMINGS.SIGNAL_MS +
      Math.floor(ROBOT_VISUAL_FLOW_TIMINGS.EXECUTING_MS / 2);
    mockRobotPageQueries({
      session: {
        ...buildRunningBotSession(),
        sessionStartAt: Date.now() - executingElapsedMs,
      },
      wasExplicitlyStopped: false,
    });
    hookMocks.useCandles.mockReturnValue({
      candles: buildDuplicateCandles(),
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.visualFlow.stage).toBe("signal");
    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ candlesReady: false }),
    );
  });

  it("keeps stale active trade visible without marking the bot as running", () => {
    mockRobotPageQueries(buildNoSessionState());
    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildPendingTrade({ id: "stale-offline" }),
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.isRunning).toBe(false);
    expect(result.current.visualFlow.stage).toBe("active_trade");
    // R259: without an active bot session, auto-trade pipeline stays
    // disabled (enabled=false) so the page does NOT re-arm new POST /trade
    // cycles. The pending overlay still renders because useActiveTrade
    // owns that side of the cache.
    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({
        activeTrade: expect.objectContaining({ id: "stale-offline" }),
        enabled: false,
      }),
    );
  });

  it("ignores a cold settled upstream result when pending was not observed locally", () => {
    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildSettledTrade({ id: "old-result" }),
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.visualFlow.stage).not.toBe("result");
    expect(result.current.visualFlow.result).toBeUndefined();
    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ activeTrade: null, enabled: true }),
    );
  });

  it("ignores a cold cancelled upstream result when pending was not observed locally", () => {
    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildCancelledTrade({ id: "old-refund" }),
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.visualFlow.stage).not.toBe("result");
    expect(result.current.visualFlow.result).toBeUndefined();
    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ activeTrade: null, enabled: true }),
    );
  });

  it("keeps result overlay for a trade observed as pending in the current page", () => {
    const observedTrade = buildPendingTrade({ id: "observed-result" });
    hookMocks.useActiveTrade.mockReturnValue({
      trade: observedTrade,
      isLoading: false,
      isError: false,
    });
    const { result, rerender } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });
    expect(result.current.visualFlow.stage).toBe("active_trade");

    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildSettledTrade({ id: observedTrade.id }),
      isLoading: false,
      isError: false,
    });
    rerender();

    expect(result.current.visualFlow.stage).toBe("result");
    expect(result.current.visualFlow.result?.outcome).toBe("win");
  });

  it("explicit start arms local visual trade flow without re-POSTing when backend already runs", () => {
    const startMutate = vi.fn();
    hookMocks.useStartBotSession.mockReturnValue({
      mutate: startMutate,
      isPending: false,
      isError: false,
    });
    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    act(() => result.current.startRobot());

    expect(startMutate).not.toHaveBeenCalled();
    expect(result.current.isRunning).toBe(true);
    expect(result.current.visualFlow.stage).not.toBe("idle");
    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ enabled: true }),
    );
  });

  it("ignores reentrant start while start mutation is pending", () => {
    const startMutate = vi.fn();
    mockRobotPageQueries(
      buildStoppedSessionState({ wasExplicitlyStopped: false }),
    );
    hookMocks.useStartBotSession.mockReturnValue({
      mutate: startMutate,
      isPending: true,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    act(() => result.current.startRobot());

    expect(startMutate).not.toHaveBeenCalled();
  });
});

describe("useRobotPageState stop overlay (P0-8 R65)", () => {
  beforeEach(() => {
    hookMocks.useRobotAutoTrade.mockClear();
    mockRobotPageQueries(
      buildStoppedSessionState({ wasExplicitlyStopped: true }),
    );
    hookMocks.useActiveTrade.mockReturnValue({
      trade: null,
      isLoading: false,
      isError: false,
    });
    hookMocks.usePlaceTrade.mockReturnValue(
      buildPlaceMutation({ data: undefined, isPending: false }),
    );
  });

  it("keeps pending place.data visible after the user requested stop", () => {
    // Manual stop is stop-after-current: DELETE /api/v2/bot/session disables
    // the next cycle but the broker order remains live until Matrix settles it.
    const stalePending = buildPendingTrade({ id: "stale-after-stop" });
    hookMocks.usePlaceTrade.mockReturnValue(
      buildPlaceMutation({ data: stalePending, isPending: false }),
    );

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.visualFlow.stage).toBe("active_trade");
    expect(result.current.visualFlow.trade?.asset).toBe("BTCUSDT");
    expect(hookMocks.useRobotAutoTrade).toHaveBeenCalledWith(
      expect.objectContaining({ activeTrade: stalePending, enabled: false }),
    );
  });

  it("keeps active trade visible while DELETE bot session is in flight", () => {
    // While the user-stop mutation is pending the session row still says
    // `isRunning: true`, so isStopping (transition.isStopping) is the only
    // signal that the backend drain is cleaning up. The overlay must respect
    // that signal and stop driving the active_trade stage immediately.
    mockRobotPageQueries(buildRobotSessionState());
    hookMocks.useStopBotSession.mockReturnValue({
      mutate: vi.fn(),
      isPending: true,
      isError: false,
    });
    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildPendingTrade({ id: "draining" }),
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.isStopping).toBe(true);
    expect(result.current.visualFlow.stage).toBe("active_trade");
    expect(result.current.visualFlow.trade?.asset).toBe("BTCUSDT");
    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ enabled: false }),
    );
  });

  it("R262: schedules a stop without firing the backend mutation while trade is pending", () => {
    const stopMutate = vi.fn();
    mockRobotPageQueries(buildRobotSessionState());
    hookMocks.useStopBotSession.mockReturnValue({
      mutate: stopMutate,
      isPending: false,
      isError: false,
    });
    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildPendingTrade({ id: "stop-after-current" }),
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    act(() => result.current.stopRobot());

    // Trade is still pending → mutation must NOT fire yet. The visual
    // flow keeps active_trade and the operator sees the red button.
    expect(stopMutate).not.toHaveBeenCalled();
    expect(result.current.scheduledStop).toBe(true);
    expect(result.current.visualFlow.stage).toBe("active_trade");
    expect(result.current.visualFlow.trade?.asset).toBe("BTCUSDT");
  });

  it("R262: cancelling a scheduled stop keeps the session alive (no mutation)", () => {
    const stopMutate = vi.fn();
    mockRobotPageQueries(buildRobotSessionState());
    hookMocks.useStopBotSession.mockReturnValue({
      mutate: stopMutate,
      isPending: false,
      isError: false,
    });
    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildPendingTrade({ id: "cancel-scheduled-stop" }),
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    act(() => result.current.stopRobot());
    expect(result.current.scheduledStop).toBe(true);

    act(() => result.current.cancelStopRobot());
    expect(result.current.scheduledStop).toBe(false);
    expect(stopMutate).not.toHaveBeenCalled();
  });

  it("R262: clicking stop with no pending trade fires the backend mutation immediately", () => {
    const stopMutate = vi.fn();
    mockRobotPageQueries(buildRobotSessionState());
    hookMocks.useStopBotSession.mockReturnValue({
      mutate: stopMutate,
      isPending: false,
      isError: false,
    });
    hookMocks.useActiveTrade.mockReturnValue({
      trade: null,
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    act(() => result.current.stopRobot());

    expect(stopMutate).toHaveBeenCalledTimes(1);
  });

  it("stops the signal window immediately without letting auto-trade loop", () => {
    const stopMutate = vi.fn();
    const signalElapsedMs = ROBOT_VISUAL_FLOW_TIMINGS.ANALYZING_MS + 1_000;
    mockRobotPageQueries({
      session: {
        ...buildRunningBotSession(),
        sessionStartAt: Date.now() - signalElapsedMs,
        updatedAt: Date.now(),
      },
      wasExplicitlyStopped: false,
    });
    hookMocks.useStopBotSession.mockReturnValue({
      mutate: stopMutate,
      isPending: false,
      isError: false,
    });
    hookMocks.useActiveTrade.mockReturnValue({
      trade: null,
      isLoading: false,
      isError: false,
    });

    const { result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    expect(result.current.visualFlow.stage).toBe("signal");
    act(() => result.current.stopRobot());

    expect(stopMutate).toHaveBeenCalledTimes(1);
    expect(result.current.visualFlow.stage).toBe("stopped");
    expect(hookMocks.useRobotAutoTrade).toHaveBeenLastCalledWith(
      expect.objectContaining({ enabled: false }),
    );
  });
});

function buildStoppedSessionState(overrides: {
  wasExplicitlyStopped: boolean;
}): BotSessionState {
  return {
    session: { ...buildRunningBotSession(), isRunning: false },
    wasExplicitlyStopped: overrides.wasExplicitlyStopped,
  };
}

