describe("useRobotPageState stop-win/stop-loss settle trigger (Track H)", () => {
  beforeEach(() => {
    hookMocks.useRobotAutoTrade.mockClear();
    hookMocks.patchBotSessionRuntime.mockClear();
    // Session with 10% stop-loss on 10 000 cents → stopLossCents = 1000
    mockRobotPageQueries(
      buildBotSessionStateWithLimits({
        stopLossPercent: 10,
        stopWinPercent: 20,
        initialBalanceCents: 10_000,
      }),
    );
    hookMocks.useActiveTrade.mockReturnValue({
      trade: null,
      isLoading: false,
      isError: false,
    });
    hookMocks.usePlaceTrade.mockReturnValue(
      buildPlaceMutation({ data: undefined, isPending: false }),
    );
  });

  it("patches sessionProfitCents without stop when trade settles within limits", async () => {
    // Profit -500 — within the 1000-cent loss cap.
    const pendingTrade = buildPendingTrade({ id: "t-within" });
    hookMocks.useActiveTrade.mockReturnValue({
      trade: pendingTrade,
      isLoading: false,
      isError: false,
    });
    const { rerender, result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });
    // Trade settles with -500 profit — within the cap
    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildWinTrade({ id: pendingTrade.id, payoutCents: 500 }),
      isLoading: false,
      isError: false,
    });
    await act(async () => {
      rerender();
    });
    // PATCH should be called with sessionProfitCents; isBotStopped absent
    const patchCalls = hookMocks.patchBotSessionRuntime.mock.calls;
    const stopPatch = patchCalls.find(
      (c: unknown[]) => (c[0] as Record<string, unknown>).isBotStopped === true,
    );
    expect(stopPatch).toBeUndefined();
    expect(result.current.sessionProfitCents).toBe(500);
  });

  it("patches isBotStopped=true and stop_loss when loss cap is exceeded", async () => {
    // Profit -1100 (> 1000 cent loss cap → stop_loss)
    const pendingTrade = buildPendingTrade({
      id: "t-loss",
      amountCents: 1_100,
    });
    hookMocks.useActiveTrade.mockReturnValue({
      trade: pendingTrade,
      isLoading: false,
      isError: false,
    });
    const { rerender, result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });
    // Settle as loss — profitCents = -1100, sessionProfitCents = -1100
    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildLossTrade({ id: pendingTrade.id, amountCents: 1_100 }),
      isLoading: false,
      isError: false,
    });
    await act(async () => {
      rerender();
    });
    const patchCalls = hookMocks.patchBotSessionRuntime.mock
      .calls as unknown[][];
    const stopPatch = patchCalls.find(
      (c) => (c[0] as Record<string, unknown>).isBotStopped === true,
    );
    expect(stopPatch).toBeDefined();
    const body = stopPatch![0] as Record<string, unknown>;
    expect(body.stopReason).toBe("stop_loss");
    expect(body.isBotStopped).toBe(true);
    expect(typeof body.sessionProfitCents).toBe("number");
    expect(result.current.isRunning).toBe(false);
    expect(result.current.stopReason).toBe("stop_loss");
    expect(result.current.sessionProfitCents).toBe(-1_100);
    expect(hookMocks.hardStopRobotAutoTradeRuntime).toHaveBeenCalled();
    await act(async () => {
      rerender();
    });
    expect(result.current.visualFlow.stage).toBe("idle");
    expect(result.current.visualFlow.detail).not.toContain(
      "Parada manual confirmada",
    );
  });

  it("patches isBotStopped=true and stop_win when win cap is reached", async () => {
    const pendingTrade = buildPendingTrade({
      id: "t-win",
      amountCents: 1_000,
    });
    hookMocks.useActiveTrade.mockReturnValue({
      trade: pendingTrade,
      isLoading: false,
      isError: false,
    });
    const { rerender, result } = renderHook(() => useRobotPageState(), {
      wrapper: TestQueryWrapper,
    });

    hookMocks.useActiveTrade.mockReturnValue({
      trade: buildWinTrade({
        id: pendingTrade.id,
        amountCents: 1_000,
        payoutCents: 3_000,
      }),
      isLoading: false,
      isError: false,
    });
    await act(async () => {
      rerender();
    });

    const patchCalls = hookMocks.patchBotSessionRuntime.mock
      .calls as unknown[][];
    const stopPatch = patchCalls.find(
      (c) => (c[0] as Record<string, unknown>).isBotStopped === true,
    );
    expect(stopPatch).toBeDefined();
    const body = stopPatch![0] as Record<string, unknown>;
    expect(body.stopReason).toBe("stop_win");
    expect(body.isBotStopped).toBe(true);
    expect(result.current.isRunning).toBe(false);
    expect(result.current.stopReason).toBe("stop_win");
    expect(result.current.sessionProfitCents).toBe(2_000);
    expect(hookMocks.hardStopRobotAutoTradeRuntime).toHaveBeenCalled();
    await act(async () => {
      rerender();
    });
    expect(result.current.visualFlow.stage).toBe("idle");
    expect(result.current.visualFlow.detail).not.toContain(
      "Parada manual confirmada",
    );
  });
});

