import { act, renderHook, waitFor } from "@testing-library/react";
import type { FC, PropsWithChildren } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  QueryClient,
  QueryClientProvider,
  useQuery,
  type QueryKey,
} from "@/lib/query";
import { FakeDeferredPromise } from "../../_fakes/FakeDeferredPromise";
import { FakeQueryFnSpy } from "../../_fakes/FakeQueryFnSpy";

function wrapperFor(client: QueryClient): FC<PropsWithChildren> {
  return function QueryWrapper({ children }) {
    return (
      <QueryClientProvider client={client}>{children}</QueryClientProvider>
    );
  };
}

afterEach(() => {
  vi.useRealTimers();
  vi.restoreAllMocks();
  setVisibilityState("visible");
});

function setVisibilityState(state: DocumentVisibilityState): void {
  Object.defineProperty(document, "visibilityState", {
    configurable: true,
    value: state,
  });
}

describe("useQuery stale fetch", () => {
  it("refetches once after invalidation despite rerenders", async () => {
    const client = new QueryClient();
    const key: QueryKey = ["rerender-once"];
    let sequence = 0;
    const fake = new FakeQueryFnSpy(async () => {
      sequence += 1;
      return `v${sequence}`;
    });
    const hook = renderHook(
      () => useQuery({ queryKey: key, queryFn: fake.fn, retry: false }),
      { wrapper: wrapperFor(client) },
    );

    await waitFor(() => expect(fake.callCount).toBe(1));
    act(() => client.invalidateQueries({ queryKey: key }));
    hook.rerender();
    hook.rerender();

    await waitFor(() => expect(fake.callCount).toBe(2));
    hook.rerender();
    expect(fake.callCount).toBe(2);
  });

  it("does not start another fetch while the entry promise is pending", () => {
    const client = new QueryClient();
    const deferred = new FakeDeferredPromise<string>();
    const fake = new FakeQueryFnSpy(() => deferred.promise);
    const hook = renderHook(
      () =>
        useQuery({
          queryKey: ["pending-dedupe"],
          queryFn: fake.fn,
          retry: false,
        }),
      { wrapper: wrapperFor(client) },
    );

    hook.rerender();
    hook.rerender();

    expect(fake.callCount).toBe(1);
    hook.unmount();
    deferred.resolve("done");
  });

  it("aborts the in-flight query when the last subscriber unmounts", async () => {
    const client = new QueryClient();
    const signalBox: { current?: AbortSignal } = {};
    const queryFn = ({ signal }: { signal: AbortSignal }): Promise<string> => {
      signalBox.current = signal;
      return new Promise((_resolve, reject) => {
        signal.addEventListener("abort", () =>
          reject(new DOMException("aborted", "AbortError")),
        );
      });
    };
    const hook = renderHook(
      () =>
        useQuery({
          queryKey: ["abort-on-unmount"],
          queryFn,
          retry: false,
        }),
      { wrapper: wrapperFor(client) },
    );

    const signal = signalBox.current;
    if (!signal) throw new Error("queryFn did not receive signal");
    expect(signal.aborted).toBe(false);
    hook.unmount();
    expect(signal.aborted).toBe(true);
    await act(async () => {});
  });
});

describe("useQueryPolling", () => {
  it("keeps polling active when one consumer of the key unmounts", async () => {
    vi.useFakeTimers();
    const client = new QueryClient();
    const fake = new FakeQueryFnSpy(async () => "ok");
    const wrapper = wrapperFor(client);
    const query = {
      queryKey: ["shared-polling"],
      queryFn: fake.fn,
      refetchInterval: 1000,
      retry: false,
    };

    const primary = renderHook(() => useQuery(query), { wrapper });
    const overlay = renderHook(() => useQuery(query), { wrapper });
    await act(async () => {});
    expect(fake.callCount).toBe(1);

    await act(async () => vi.advanceTimersByTimeAsync(1000));
    expect(fake.callCount).toBe(2);
    overlay.unmount();

    await act(async () => vi.advanceTimersByTimeAsync(1000));
    expect(fake.callCount).toBe(3);
    primary.unmount();

    await act(async () => vi.advanceTimersByTimeAsync(1000));
    expect(fake.callCount).toBe(3);
  });

  it("replaces the interval without leaking timers when cadence changes", () => {
    vi.useFakeTimers();
    const client = new QueryClient();
    const fake = new FakeQueryFnSpy(async () => "ok");
    const { rerender, unmount } = renderHook(
      ({ interval }) =>
        useQuery({
          queryKey: ["polling-cadence"],
          queryFn: fake.fn,
          refetchInterval: interval,
          retry: false,
        }),
      { initialProps: { interval: 1000 }, wrapper: wrapperFor(client) },
    );

    expect(vi.getTimerCount()).toBe(1);
    rerender({ interval: 500 });
    expect(vi.getTimerCount()).toBe(1);
    unmount();
    expect(vi.getTimerCount()).toBe(0);
  });

  it("does not register polling while the query is disabled", async () => {
    vi.useFakeTimers();
    const client = new QueryClient();
    const fake = new FakeQueryFnSpy(async () => "ok");
    const hook = renderHook(
      () =>
        useQuery({
          queryKey: ["polling-disabled"],
          queryFn: fake.fn,
          enabled: false,
          refetchInterval: 1000,
          retry: false,
        }),
      { wrapper: wrapperFor(client) },
    );

    expect(vi.getTimerCount()).toBe(0);
    await act(async () => vi.advanceTimersByTimeAsync(1000));
    expect(fake.callCount).toBe(0);
    hook.unmount();
  });

  it("pauses polling in hidden tabs when background refetch is disabled", async () => {
    vi.useFakeTimers();
    setVisibilityState("hidden");
    const client = new QueryClient();
    const fake = new FakeQueryFnSpy(async () => "ok");
    const hook = renderHook(
      () =>
        useQuery({
          queryKey: ["polling-visible-only"],
          queryFn: fake.fn,
          refetchInterval: 1000,
          refetchIntervalInBackground: false,
          retry: false,
        }),
      { wrapper: wrapperFor(client) },
    );
    await act(async () => {});
    expect(fake.callCount).toBe(1);
    expect(vi.getTimerCount()).toBe(0);

    setVisibilityState("visible");
    act(() => document.dispatchEvent(new Event("visibilitychange")));
    expect(vi.getTimerCount()).toBe(1);
    await act(async () => vi.advanceTimersByTimeAsync(1000));
    expect(fake.callCount).toBe(2);
    hook.unmount();
  });

  it("keeps default background polling active while the tab is hidden", async () => {
    vi.useFakeTimers();
    setVisibilityState("hidden");
    const client = new QueryClient();
    const fake = new FakeQueryFnSpy(async () => "ok");
    const hook = renderHook(
      () =>
        useQuery({
          queryKey: ["polling-background-default"],
          queryFn: fake.fn,
          refetchInterval: 1000,
          retry: false,
        }),
      { wrapper: wrapperFor(client) },
    );
    await act(async () => {});
    expect(vi.getTimerCount()).toBe(1);
    await act(async () => vi.advanceTimersByTimeAsync(1000));
    expect(fake.callCount).toBe(2);
    hook.unmount();
  });

  it("removes the visibility listener when visible-only polling unmounts", () => {
    vi.useFakeTimers();
    const addSpy = vi.spyOn(document, "addEventListener");
    const removeSpy = vi.spyOn(document, "removeEventListener");
    const client = new QueryClient();
    const fake = new FakeQueryFnSpy(async () => "ok");
    const hook = renderHook(
      () =>
        useQuery({
          queryKey: ["polling-listener-cleanup"],
          queryFn: fake.fn,
          refetchInterval: 1000,
          refetchIntervalInBackground: false,
          retry: false,
        }),
      { wrapper: wrapperFor(client) },
    );

    expect(addSpy).toHaveBeenCalledWith(
      "visibilitychange",
      expect.any(Function),
    );
    hook.unmount();
    expect(removeSpy).toHaveBeenCalledWith(
      "visibilitychange",
      expect.any(Function),
    );
  });

  it("does not subscribe visibility listener for default background polling", () => {
    vi.useFakeTimers();
    const addSpy = vi.spyOn(document, "addEventListener");
    const client = new QueryClient();
    const fake = new FakeQueryFnSpy(async () => "ok");
    const hook = renderHook(
      () =>
        useQuery({
          queryKey: ["polling-no-listener"],
          queryFn: fake.fn,
          refetchInterval: 1000,
          retry: false,
        }),
      { wrapper: wrapperFor(client) },
    );

    expect(addSpy).not.toHaveBeenCalledWith(
      "visibilitychange",
      expect.any(Function),
    );
    hook.unmount();
  });
});

