/**
 * R261/R262 invariants for the sticky-overlay guard.
 *
 * R261 contract: the stage-machine MUST NOT regress from active_trade/result
 * back to analyzing/awaiting_signal while a pending trade still lives in
 * the cache.
 *
 * R262 contract: the sticky replay MUST recompute the trade timer from
 * `nowMs` instead of replaying the snapshot captured at observation time —
 * else the operator sees the "timer não abaixa" freeze that birthed R262.
 *
 * Tests run the pure helpers directly (no React renderer, no fake timers)
 * so they stay F.I.R.S.T. They act as the canonical specification for the
 * post-R262 contract.
 */

import { afterEach, describe, expect, it } from "vitest";
