// Default rebuilder: feeds the stored TradeView through resolveTradeOverlay
// so the test exercises the real production code path (no inline stubs).
const defaultRebuilder: StickyOverlayRebuilder = (params) =>
  resolveTradeOverlay(
    { activeTrade: params.tradeView, isPlacingTrade: false },
    params.sessionProfitCents,
    params.nowMs,
  );

function buildActiveTradeOverlayAt(
  trade: TradeView,
  nowMs: number,
): RobotTradeOverlay {
  const overlay = resolveTradeOverlay(
    { activeTrade: trade, isPlacingTrade: false },
    0,
    nowMs,
  );
  if (!overlay) throw new Error("expected overlay for pending trade");
  return overlay;
}

const EXECUTING_OVERLAY: RobotTradeOverlay = { stage: "executing" };

// eslint-disable-next-line max-lines-per-function
describe("reconcileStickyOverlay (R261/R262 architecture invariant)", () => {
