    // signal stage of cycle >= 1, and `gateOverlayForStageMinimum`
    // suppresses the active_trade overlay until 6 s elapse. Without v3.1
    // the leftover `result` sticky from trade #1 stayed and the rebuilder
    // for the OLD (settled) tradeView returned null → UI regressed to
    // signal. v3.1: when upstream has a NEW pending tradeView whose id
    // differs from the sticky's id (or the sticky is a result), capture
    // it directly as active_trade so the very next render paints the
    // fresh trade.
    const ref = newStickyRef();
    const oldTrade = pendingTradeFixture({ id: "trade-old" });
    const newTrade = pendingTradeFixture({
      id: "trade-new",
      createdAt: new Date(TRADE_CREATED_AT_MS + 80_000).toISOString(),
      expirationTimestamp: TRADE_CREATED_AT_MS + 140_000,
