    expect(ref.current?.capturedStage).toBe("result");

    // Now a NEW pending trade lands in upstream, but the gate suppressed
    // the overlay (null going into reconcileStickyOverlay). v3.1 must
    // upgrade the sticky to active_trade for the NEW tradeView.
    const upgraded = reconcileStickyOverlay({
      overlay: null,
      upstreamTradeView: newTrade,
      hasPendingTradeInCache: true,
      nowMs: TRADE_CREATED_AT_MS + 80_500,
      sessionProfitCents: 0,
      stickyRef: ref,
      rebuilder: defaultRebuilder,
    });
    expect(upgraded?.stage).toBe("active_trade");
    expect(ref.current?.capturedStage).toBe("active_trade");
    expect(ref.current?.tradeView.id).toBe("trade-new");
  });

  it("R262 v4: phase 1 refresh from upstream keeps sticky alive across cycle wraps and gate suppressions", () => {
    // The real-trade E2E exposed this: during a 60s trade, the cycle wrap
    // at 21s makes gateOverlayForStageMinimum suppress the overlay for
    // the first 6s of every analyzing/awaiting/signal cycle. Each tick,
    // upstream still has the trade pending — phase 1 of v4 syncs the
    // sticky observedAtMs from upstream, so the TTL never expires while
    // the trade is alive. (v3 refreshed on replay regardless of upstream
    // → broke when trade settled and upstream went null: sticky lingered
    // forever.)
    const ref = newStickyRef();
    const trade = pendingTradeFixture();
    const observedAt = TRADE_CREATED_AT_MS + 1_000;
    reconcileStickyOverlay({
      overlay: buildActiveTradeOverlayAt(trade, observedAt),
      upstreamTradeView: trade,
      hasPendingTradeInCache: true,
      nowMs: observedAt,
      sessionProfitCents: 0,
      stickyRef: ref,
      rebuilder: defaultRebuilder,
    });

    // 30 ticks at 1 s each. Upstream returns the same pending trade every
    // tick. Overlay is suppressed by gate (null going into the guard).
    let cursor = observedAt;
    for (let step = 0; step < 30; step += 1) {
      cursor += 1_000;
      const replay = reconcileStickyOverlay({
        overlay: null,
        upstreamTradeView: trade,
        hasPendingTradeInCache: true,
        nowMs: cursor,
        sessionProfitCents: 0,
        stickyRef: ref,
        rebuilder: defaultRebuilder,
      });
      expect(replay?.stage, `step=${step} (t+${cursor - observedAt}ms)`).toBe(
        "active_trade",
      );
    }
  });

  it("R262 v4: sticky transitions to result and drops cleanly when upstream observes settle (no infinite active_trade)", () => {
    // The exact bug v4 fixes: after trade settles, upstream returns
    // `status=win` (sticky-active-trade pin), then null. Without phase 1
    // sync, the sticky still says capturedStage='active_trade' for the
    // pending tradeView snapshot → replay returns active_trade overlay
    // FOREVER, blocking the visual cycle from advancing past active_trade
    // (auto-trade gate `isRobotAutoTradeSignalReady` requires
    // signal/executing → no new trade fires).
    const ref = newStickyRef();
    const trade = pendingTradeFixture();
    const t0 = TRADE_CREATED_AT_MS + 1_000;

    // Step 1: trade pending observed
    reconcileStickyOverlay({
      overlay: buildActiveTradeOverlayAt(trade, t0),
      upstreamTradeView: trade,
      hasPendingTradeInCache: true,
      nowMs: t0,
      sessionProfitCents: 0,
      stickyRef: ref,
      rebuilder: defaultRebuilder,
    });
    expect(ref.current?.capturedStage).toBe("active_trade");

    // Step 2: trade settles — upstream returns same trade with status=win.
