    const settled = { ...trade, status: "win", payoutCents: 800 } as TradeView;
    reconcileStickyOverlay({
      overlay: null,
      upstreamTradeView: settled,
      hasPendingTradeInCache: false,
      nowMs: t0 + 60_000,
      sessionProfitCents: 0,
      stickyRef: ref,
      rebuilder: defaultRebuilder,
    });
    expect(ref.current?.capturedStage).toBe("result");

    // Step 3: upstream goes null after settle pin elapses. Sticky should
    // age out within TTL — no replay forever as active_trade.
    const replayAfterTtl = reconcileStickyOverlay({
      overlay: null,
      upstreamTradeView: null,
      hasPendingTradeInCache: false,
      nowMs: t0 + 60_000 + STICKY_OVERLAY_TTL_MS + 1,
      sessionProfitCents: 0,
      stickyRef: ref,
      rebuilder: defaultRebuilder,
    });
    expect(replayAfterTtl).toBeNull();
    expect(ref.current).toBeNull();
  });

  it("R262 v2: replays active_trade sticky even when upstream cache reads false (transient null window)", () => {
    // The real-trade E2E exposed this: during a 60s trade, /trade/active
    // momentarily returns null between polls. The R262 first cut gated the
    // replay on `hasPendingTradeInCache`, which reads `false` during that
    // exact window — so the guard didn't help, and the UI regressed to
    // signal/analyzing mid-trade. v2: active_trade sticky always replays
    // within TTL; the rebuilder uses the captured TradeView so the timer
    // still ticks (R262 v1 fix), and the stage stays active_trade until
    // either upstream comes back or the TTL elapses.
    const ref = newStickyRef();
    const trade = pendingTradeFixture();
    const observedAt = TRADE_CREATED_AT_MS + 1_000;
    reconcileStickyOverlay({
      overlay: buildActiveTradeOverlayAt(trade, observedAt),
      upstreamTradeView: trade,
      hasPendingTradeInCache: true,
