      upstreamTradeView: null,
      hasPendingTradeInCache: false,
      nowMs: observedAt + 1_000,
      sessionProfitCents: 0,
      stickyRef: ref,
      rebuilder: defaultRebuilder,
    });

    expect(next?.stage).toBe("active_trade");
