  it("R262 v2: result sticky still requires hasPendingTradeInCache to avoid replaying past cooldown", () => {
    const ref = newStickyRef();
    const win = settledWinFixture();
    const observedAt = TRADE_CREATED_AT_MS + 60_500;
    reconcileStickyOverlay({
