    expect(next).toBe(liveResult);
    expect(ref.current?.capturedStage).toBe("result");
  });

  it("passes the executing overlay through without recording it", () => {
    const ref = newStickyRef();
    const next = reconcileStickyOverlay({
      overlay: EXECUTING_OVERLAY,
      upstreamTradeView: null,
      hasPendingTradeInCache: true,
