      stickyRef: ref,
      rebuilder: defaultRebuilder,
    });

    expect(next).toBe(EXECUTING_OVERLAY);
    expect(ref.current).toBeNull();
  });

  it("replays sticky overlay even at the very edge of the TTL window", () => {
    const ref = newStickyRef();
    const trade = pendingTradeFixture();
    const observedAt = TRADE_CREATED_AT_MS + 1_000;
    reconcileStickyOverlay({
      overlay: buildActiveTradeOverlayAt(trade, observedAt),
      upstreamTradeView: trade,
      hasPendingTradeInCache: true,
      nowMs: observedAt,
      sessionProfitCents: 0,
      stickyRef: ref,
      rebuilder: defaultRebuilder,
    });

    const onEdge = reconcileStickyOverlay({
      overlay: null,
      upstreamTradeView: null,
      hasPendingTradeInCache: true,
      nowMs: observedAt + STICKY_OVERLAY_TTL_MS - 1,
      sessionProfitCents: 0,
      stickyRef: ref,
      rebuilder: defaultRebuilder,
    });

    expect(onEdge?.stage).toBe("active_trade");
  });

  it("overwrites the sticky cache when a fresh active_trade arrives", () => {
    const ref = newStickyRef();
    const trade = pendingTradeFixture();
    const t0 = TRADE_CREATED_AT_MS + 1_000;
    const t1 = t0 + 5_000;
    reconcileStickyOverlay({
      overlay: buildActiveTradeOverlayAt(trade, t0),
      upstreamTradeView: trade,
      hasPendingTradeInCache: true,
      nowMs: t0,
      sessionProfitCents: 0,
