  });
});

describe("assertNoStageBackslide (R261 contract enforcement)", () => {
  it("throws on active_trade -> analyzing while a trade is pending", () => {
    expect(() =>
      assertNoStageBackslide({
        prev: "active_trade",
        next: "analyzing",
        hasPendingTradeInCache: true,
      }),
    ).toThrow(/regressed from active_trade to analyzing/);
  });

  it("throws on result -> signal while a trade is pending", () => {
    expect(() =>
      assertNoStageBackslide({
        prev: "result",
        next: "signal",
        hasPendingTradeInCache: true,
      }),
    ).toThrow(/regressed from result to signal/);
  });

  it("does not throw when no pending trade is in cache (post-trade idle)", () => {
    expect(() =>
      assertNoStageBackslide({
        prev: "result",
        next: "analyzing",
        hasPendingTradeInCache: false,
      }),
    ).not.toThrow();
  });

  it("does not throw on the legitimate active_trade -> result transition", () => {
    expect(() =>
      assertNoStageBackslide({
        prev: "active_trade",
        next: "result",
        hasPendingTradeInCache: true,
      }),
    ).not.toThrow();
  });

  it("does not throw on analyzing -> signal (forward progress)", () => {
    expect(() =>
      assertNoStageBackslide({
        prev: "analyzing",
        next: "signal",
        hasPendingTradeInCache: false,
      }),
    ).not.toThrow();
  });
});

describe("R262 stage trace: simulated lifecycle with ticking timer", () => {
  it("holds active_trade through transient null windows AND advances the timer", () => {
    const ref = newStickyRef();
    const trade = pendingTradeFixture();
    const frames = [
      { dt: 0, hasOverlay: true, hasPending: true },
      { dt: 1_000, hasOverlay: true, hasPending: true },
      { dt: 2_000, hasOverlay: false, hasPending: true }, // upstream blips null
      { dt: 4_000, hasOverlay: false, hasPending: true }, // still null
      { dt: 5_000, hasOverlay: true, hasPending: true }, // upstream recovers
    ];

    const observedSeconds: number[] = [];
    let nowMs = TRADE_CREATED_AT_MS + 5_000; // start 5s into the trade
    for (const frame of frames) {
      nowMs = TRADE_CREATED_AT_MS + 5_000 + frame.dt;
      const live = frame.hasOverlay
        ? buildActiveTradeOverlayAt(trade, nowMs)
        : null;
      const overlay = reconcileStickyOverlay({
        overlay: live,
        upstreamTradeView: frame.hasOverlay ? trade : null,
        hasPendingTradeInCache: frame.hasPending,
        nowMs,
        sessionProfitCents: 0,
        stickyRef: ref,
        rebuilder: defaultRebuilder,
      });
      expect(overlay?.stage).toBe("active_trade");
      observedSeconds.push(overlay?.trade?.expiresInSeconds ?? -1);
    }

    // Timer must decrement monotonically across all 5 frames — including
    // the two null-overlay frames where the sticky guard takes over.
    for (let i = 1; i < observedSeconds.length; i++) {
      expect(observedSeconds[i]).toBeLessThanOrEqual(observedSeconds[i - 1]!);
    }
    // Sanity: across 5 s of wall clock, the 60 s timer should drop by ≥4 s.
    expect(observedSeconds[0]! - observedSeconds[4]!).toBeGreaterThanOrEqual(4);
  });
});

