import { describe, expect, it } from "vitest";
import type { RobotVisualFlow } from "./components/flow/robot-visual-flow";
import { resolveSignalCandleRequest } from "./use-robot-auto-trade-binding";

function flowFixture(
  overrides: Partial<RobotVisualFlow> = {},
): RobotVisualFlow {
  return {
    stage: "idle",
    statusText: "IA PRONTA",
    title: "Aguardando inicio",
    detail: "Configure a estrategia para iniciar o robo.",
    strategyTitle: null,
    bankPercent: null,
    cycleIndex: 0,
    ...overrides,
  };
}

describe("resolveSignalCandleRequest", () => {
  it("issue #190: disables candle polling outside signal stages", () => {
    const request = resolveSignalCandleRequest(
      flowFixture({
        stage: "active_trade",
        signal: { asset: "BTCUSDT", direction: "CALL", confidence: 82 },
      }),
    );

    expect(request).toEqual({ options: {}, required: false, symbol: "" });
  });

  it("issue #190: enables realtime candles during signal and executing", () => {
    const signal = {
      asset: "BTCUSDT",
      direction: "CALL",
      confidence: 82,
    } as const;
    const signalRequest = resolveSignalCandleRequest(
      flowFixture({ stage: "signal", signal }),
    );
    const executingRequest = resolveSignalCandleRequest(
      flowFixture({ stage: "executing", signal }),
    );

    expect(signalRequest).toEqual({
      options: { realtime: true, refetchIntervalMs: 2_000 },
      required: true,
      symbol: "BTCUSDT",
    });
    expect(executingRequest).toEqual(signalRequest);
  });
});
